//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 002 *** -- Starts here 
// The purpose of the below code is to draw a grid on the Workspace automatically. It can also clear all 
// canvas drawings (Grid Initialisation and Axis Initialisation) by using MODE 1 (aka. Deletion = True).



var gridwidth = xLen;  // This variable defines the total width that the Grid X-Axis line will stretch to. 
                       // (fill up).

var gridheight = yLen; // This variable defines the total height that the Grid Y-Axis will stretch to. 
                       // (fill up). 

var padding = 0; // This variable defines the padding between the Grid cells themselves, and the overall Grid 
                 // from the Object and File Menus themselves.  

var gridcellsCreatedOnX = 0; // DEBUGGING VALUE :: This value holds the number of iterations that this function  
                             // has gone through to produce one concurrent line of Grid Cells, so that I can 
                             // see if the function is filling up the Workspace size itself, or another metric 
                             // I am unsure of. 
                             
var gridcellsCreatedOnY = 0; // DEBUGGING VALUE :: This value holds the number of iterations that this function  
                             // has gone through to produce fill the Workspace up on the Y-Axis by duplicating 
                             // rows of Grid Cells on the X-Axis, so that I can see if the function is filling 
                             // up the Workspace size itself, or another metric I am unsure of. 

var canvas = document.getElementById("GridCanvas"); // Fetches the canvas ID that was defined 
                                                    // in the HTML div "Workspace" -> "GridContainer" 
                                                    // -> "Grid Canvas"

var gridcell = canvas.getContext("2d"); //  This instruction defines a two-dimensional cell for the grid 

function drawGrid(GRIDMODE, gridColour) {   //This function repeatedly draws a cell until there is a full row of cells to fill 
                                            // gridwidth and grid height. 

  if (GRIDMODE == 0) {  // If this function is called with a Mode of 0, aka. Deletion Mode = False, then control flow will 
                        // branch into here and begin building a new Grid on the HTML Canavas inside of the Workspace. 

    //X AXIS GRID CELL LOOP : 
    for (var x = 0; x <= gridwidth; x += 10) {  // This iterative loop tells each cell how wide they should be on 
                                                // the X-Axis and repeatedly draws said cell until it there is a row 
                                                // of gridcells that fill the gridwidth. 
                                                  // !-> There is a critical web error if x += 0 or x += -0 which 
                                                  // crashes the webpage - avoid this mathematical error. 

      gridcell.moveTo(0.5 + x + padding, padding);    // This instruction draws the border around each cell and
                                                      // constrols the resolution of each drawn border line. 
                                                        // We can change the resolution by modifying the float 
                                                        // value. 

      gridcell.lineTo(0.0 + x + padding, gridheight + padding);   // This instruction then manipulates the 
                                                                  // drawn border line to give it a skew effect. 
                                                                    // Set it to 0 if no skew/tilt is necessary. 
                                                                    // We can change the resolution by 
                                                                    // modifying the float value. 

      gridcellsCreatedOnX = gridcellsCreatedOnX + 1; // To update the debugging variable seen above. 

    };  // The construction of Grid Cells on the X-Axis ends here. 

    //Y AXIS GRID CELL LOOP : 
    for (var x = 0; x <= gridheight; x += 10) { // this iterative loop tells each cell how tall they should be on 
                                                // the Y-Axis and repeatedly draws said cell until there is a 
                                                // column of gridcells that fill the gridheight. 
                                                  // !-> There is a critical web error if x+= 0 or x += -0 which
                                                  // crashes the webpage - avoid this mathematical error. 

      gridcell.moveTo(padding, 0.5 + x + padding);    // This instruction draws the border around each cell and
                                                      // controls the resolution of each drawn border line.
                                                        // We can change the resolution by modifying the float 
                                                        // value. 

      gridcell.lineTo(gridwidth + padding, 0.5 + x + padding);    // This instruction then manipulates the 
                                                                  // drawn border line to give it a skew effect. 
                                                                    // Set it to 0 if no skew/tilt is necessary. 
                                                                    // We can change the resolution by 
                                                                    // modifying the float value. 

      gridcellsCreatedOnY = gridcellsCreatedOnY + 1; // To update the debugging variable seen above. 

    };  // The construction of Grid Cells on the Y-Axis ends here. 

    console.log(gridcellsCreatedOnY, gridcellsCreatedOnX, "griddcells created with Y | X");  // DEBUGGING INSTRUCTION :: 
                                                                                             // For telling me how many 
                                                                                             // grid "cells" were created 
                                                                                             // on each row and how many 
                                                                                             // were produced on each 
                                                                                             // column so that I can 
                                                                                             // understand how this 
                                                                                             // function operates within 
                                                                                             // the realms of the Workspace 
                                                                                             // sizing and styling. 


    //GLOBAL MODIFIER DEFINITIONS : 
    gridcell.lineWidth = 0.1;   // This instruction manually tells the drawGrid fucntion how thick each 
                                // line should be after every cell has been initialised. In this case, we 
                                // set the thickness of each border to be 0.1 pixels. 

    gridcell.strokeStyle = gridColour;   // This instruction manually tells the drawGrid function what colour
                                          // the drawn borders should appear as. In this case, we set the default 
                                          // border colour to black (#000000).

    gridcell.stroke();  // This instruction initialises the variables above to draw a cell with the desired
                        // lineWidth and strokeStyle 

  } else if (GRIDMODE == 1) {  // If this function is called with a Mode of 1, aka. Deletion Mode = True, then control flow will 
                               // branch into here and begin clearing the entire Workspace from all Canvas drawings. 

    gridcell.clearRect(0,0,2147483647,2147483647);  // The entire canvas is cleared from position 0, 0 (X, Y) on the Workspace, 
                                                    // to the 32-bit integer limit on the X and Y Axies of the Workspace canvas, 
                                                    // to ensure all previous drawings of the Grid have been cleared and wiped 
                                                    // fully.  

  } else {  // If the inputted mode is not recognised, then control flow will branch into this decision here. 

    console.log("Mode inputted is unknown. -- ERROR");  // DEBUGGING INSTRUCTION :: For telling me that whatever mode was 
                                                        // just set for the grid drawer is invalid, which indicates a 
                                                        // branching error. 

  };  // The branching for the various modes available for the Grid drawing function end here. 

}; // The function that calculates the necessary Grid visuals ends here. 

drawGrid(0, GridLineColour); // This instruction initialises the drawGrid to repeatedly draw individual cells until 
                             // the entirety of the grids' height and width is filled, with the calculated function
                             // output. 
                             // The "drawGrid()" function is not automatic, and must be called with the correct 
                             // parameters to draw a grid correctly onto the Workspace canvas when the end user 
                             // starts Simboard up. 



// *** SCRIPT 002 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 003 *** -- Starts here 
// The purpose of the below code is to draw both axies (X and Y) on the Workspace automatically. It can 
// also clear all canvas drawings (Grid Initialisation and Axis Initialisation) by using MODE 1 (aka. 
// Deletion = True).



//GLOBAL MODIFIER DEFINITIONS : 
axisWidth = xLen;   // States that the X Axis line should stretch to a defined limit
                      // defined in the Global Variables section. (This prevents magic
                      // numbers!)

axisHeight = yLen;   // States that the Y Axis line should stretch to a defined limit 
                      // defined in the Global Variables sections. (This prevents magic
                      // numbers!)
        
function drawAxis(AXISMODE, AxisYRGB, AxisXRGB) {  // This function produces the axis lines for the Workspace UI. 

  if (AXISMODE == 0) {  // If this function is called with a Mode of 0, aka. Deletion Mode = False, then control flow will 
                        // branch into here and begin building a new set of X and Y Axies onto the HTML Canavas inside of 
                        // the Workspace. 

    var canvas0 = document.getElementById("GridCanvas"); // Fetches the canvas ID that was defined 
                                                              // in the HTML div "Workspace" -> "GridContainer" 
                                                              // -> "Grid Canvas"
                                                         // This canvas reference will serve the Y-Axis being 
                                                         // drawn. 

    var canvas1 = document.getElementById("GridCanvas"); // Fetches the canvas ID that was defined 
                                                              // in the HTML div "Workspace" -> "GridContainer" 
                                                              // -> "Grid Canvas"
                                                         // This canvas reference will serve the X-Axis being 
                                                         // drawn. 

    var axisLineY = canvas0.getContext("2d"); // This instruction defines the Y-Axis as a 2 dimensional line. 

    axisLineY.beginPath(); // The JavaScript pen will begin its path at position 0, 0 (X, Y) and is given orders 
                           // to move wherever a "moveTo()" command is called. 

    axisLineY.moveTo((canvas.width)/2, 0); // The JavaScript Pen will move from 0, 0 (X, Y) to half way through 
                                           // the Workspace. 

    console.log(axisWidth/2);  // DEBUGGING INSTRUCTION :: For checking how wide the Workspace is halved, which gives the 
                               // Workspace a sense of scale.

    axisLineY.lineTo((canvas.width)/2, canvas.height); // The JavaScript Pen will push down, and draws a line 
                                                       // from the Top-Middle of the Workspace Canvas, all the 
                                                       // way down, in a straight manner, for the Y-Axis. 

    axisLineY.strokeStyle = AxisYRGB; // Now that the necessary calculations have been conceptualised by the 
                                      // JavaScript pen, it is then told that when it does "push down the pen 
                                      // and draw", that the "ink" colour should be the parsed parameter for 
                                      // the Y-Axis colour. 

    axisLineY.lineWidth = 1.5;  // Now that the necessary calculations have been conceptualised by the 
                                // JavaScript pen, it is then told that when it does "push down the pen 
                                // and draw", that the "pen-tip" thickness should be 1.5 pixels in width / 
                                // diameter. 

    axisLineY.stroke(); // The JavaScript pen is then told to carry out its previously told instructions, to 
                        // which, it will do so, and draw a noticeable limitless Green line for the Y-Axis. 

    var axisLineX = canvas1.getContext("2d"); // This instruction defines the X-Axis as a 2 dimensional line. 

    axisLineX.beginPath(); // The JavaScript pen will begin its path at position 0, 0 (X, Y) and is given orders 
                           // to move wherever a "moveTo()" command is called. 

    axisLineX.moveTo(0, (canvas.height)/2); // The JavaScript Pen will move from 0, 0 (X, Y) to half way down 
                                            // the Workspace. 

    console.log(axisWidth/2); // DEBUGGING INSTRUCTION :: For checking how wide the Workspace is halved, which gives the 
                              // Workspace a sense of scale. 

    axisLineX.lineTo(canvas.width, (canvas.height)/2);  // The JavaScript Pen will push down, and draws a line 
                                                        // from the Middle-Left of the Workspace Canvas, all the 
                                                        // way to the Middle-Right, in a straight manner, for the 
                                                        // X-Axis.  

    axisLineX.strokeStyle = AxisXRGB; // Now that the necessary calculations have been conceptualised by the 
                                      // JavaScript pen, it is then told that when it does "push down the pen 
                                      // and draw", that the "ink" colour should be the parsed parameter for 
                                      // the X-Axis colour. 

    axisLineX.lineWidth = 1.5;  // Now that the necessary calculations have been conceptualised by the 
                                // JavaScript pen, it is then told that when it does "push down the pen 
                                // and draw", that the "pen-tip" thickness should be 1.5 pixels in width / 
                                // diameter. 

    axisLineX.stroke(); // The JavaScript pen is then told to carry out its previously told instructions, to 
                        // which, it will do so, and draw a noticeable limitless Red line for the X-Axis. 


  } else if (AXISMODE == 1) {  // If this function is called with a Mode of 1, aka. Deletion Mode = True, then control flow will 
                               // branch into here and begin clearing the entire Workspace from all Canvas drawings. 

    gridcell.clearRect(0,0,999,999);  // The entire canvas is cleared from position 0, 0 (X, Y) on the Workspace, 
                                      // to the 32-bit integer limit on the X and Y Axies of the Workspace canvas, 
                                      // to ensure all previous drawings of the Grid have been cleared and wiped 
                                      // fully.  

  } else {  // If the inputted mode is not recognised, then control flow will branch into this decision here. 

    console.log("Mode inputted is unknown. -- ERROR");  // DEBUGGING INSTRUCTION :: For telling me that whatever mode was 
                                                        // just set for the grid drawer is invalid, which indicates a 
                                                        // branching error. 

  };  // The branching for the various modes available for the Axis drawing function end here. 

}; // The function that produces the correct Axis measurements ends here. 

