//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 015 *** -- Starts here 
// The purpose of the below code is to calculate the dot product of two vectors, and then normalise them to
// get a vector direction. The reason this function was implemented was to assist the drawing of non-linear 
// wire lines drawn on screen, as I thought this function would be necessary for the system to calculate 
// where two objects are, and then draw the non-linear line in a way that matches their positions (incase 
// one was behind the other, etc). THIS FUNCTION IS NOW REDUNDANT AS THIS PROCESS IS HANDLED AS A "MIDPOINT"
// IN THE HTML PATH ELEMENT CREATION PROCESS.

//*$%

function FastDotThenNormalise(VectorA, VectorB){ // This function, when called, takes in two Vector values 
                                                 // (A and B).

  // Firstly, the DOT PRODUCT between two vectors is calculated, which returns a value between -1 and 1, 
  // depending on whether the vector is facing away or towards the target position. 
  let result = 0; // The variable for holding the DOT PRODUCT answer is held here, and is defaulted to 0
                  // (perpendicular to the target vector). 
  
  for (let i = 0; i < VectorA.length; i++) {  // A vector contains two values for X and Y, and therefore, 
                                              // this program must iterate through said elements. 
                                              // This leads to four elements that need to be iterated 
                                              // through as both vectors should have an X and Y value. 

    result += VectorA[i] * VectorB[i];  // The summnation of the vectors are added onto each other, which 
                                        // leads to a final total scalar product.

  };  // The iteration through each Vector value (2d vector = 2 elements/numbers, 3d vector = 3 elements/
      // numbers etc.) ends here. 

  // Then, the vector shall be normalised so that we can return a value to the visual wire line connection 
  // handler, in order to give it the ability to make a decision on whether orthogonal or curved wire lines 
  // should appear inverted or regular if the source node is infront or behind the target node on any axis. 
  min = result; // The minimum value should be the result, as it is the only vector we are operating on 
                // in this operation. 

  max = result; // The maximum value should be the result, as it is the only vector we are operating on 
                // in this operation. 

  NormalisedDot = (result - min) / (max - min); // This formula calculates the normalised direction value 
                                                // of the vector by shifting the result until it is zero, 
                                                // yet spreading the result until it represents the range 
                                                // of data accurately. 

  return result, NormalisedDot; // Both the DOT PRODUCT of both parsed vectors and the NORMALISED DOT 
                                // PRODUCT of both parsed vectors are returned to wherever this function 
                                // is called. 

};  // The function for calculating the dot produce and normalised vector of two vector values ends here. 



