//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 016 *** -- Starts here 
// The purpose of the below code is to take data as parameters from SCRIPT 014 and then to initialise a 
// visual wire line connection. Then, a further function is called to set up the connection in the 
// backend logic of Simboard, so that the circuit can be properly simulated and the project file can be 
// saved and loaded again. 



function initConnect(MODE, PARSED_PRD){ // This function draws the connection and calls another function to add 
                                        // it to a save stack, and does this by utilising a sparse range of key 
                                        // parameters noted below, taken from the "ioCheck()" function seen above. 

  INPUTREFERENCE = PARSED_PRD.INPUT.parentNode.parentNode; // We store the reference to the Input Pins' Logic Gate 
                                                           // Object Container element variable attribute. 

  OUTPUTREFERENCE = PARSED_PRD.OUTPUT.parentNode.parentNode; // We store the reference to the Output Pins' Logic Gate 
                                                             // Object Container element variable attribute.  

  INPUTID = PARSED_PRD.PARENTINPUTUID; // We store the IOPARSE "Parent Input Unique ID" variable attribute. 

  OUTPUTID = PARSED_PRD.PARENTOUTPUTUID; // We store the IOPARSE "Parent Output Unique ID" variable attribute. 

  INPUTTYPE = PARSED_PRD.RECEIVERTYPE; // We store the IOPARSE "Receiver Type" variable attribute. 

  OUTPUTTYPE = PARSED_PRD.TRANSMITTERTYPE; // We store the IOPARSE "Transmitter Type" variable attribute. 

  GATEREFERENCE_I = PARSED_PRD.INPUT; // We store the IOPARSE "Input" variable attribute. 

  GATEREFERENCE_O = PARSED_PRD.OUTPUT; // We store the IOPARSE "Output" variable attribute. 

  INPUTREFLOCATIONX = PARSED_PRD.INPUTPOSITIONX; // We store the IOPARSE "Input Position X Axis" variable attribute. 

  INPUTREFLOCATIONY = PARSED_PRD.INPUTPOSITIONY; // We store the IOPARSE "Input Position Y Axis" variable attribute. 

  OUTPUTREFLOCATIONX = PARSED_PRD.OUTPUTPOSITIONX; // We store the IOPARSE "Output Position X Axis" variable attribute. 

  OUTPUTREFLOCATIONY = PARSED_PRD.OUTPUTPOSITIONY; // We store the IOPARSE "Output Position Y Axis" variable attribute. 

  DRAWINPUTLOCATIONX = PARSED_PRD.INPUTPOSITIONX; // We store the IOPARSE "Input Position X Axis" variable attribute. 
                                                    // !-> (Possible duplicate variable - no reason why...)

  DRAWINPUTLOCATIONY = PARSED_PRD.INPUTPOSITIONY; // We store the IOPARSE "Input Position Y Axis" variable attribute. 
                                                    // !-> (Possible duplicate variable - no reason why...)

  DRAWOUTPUTLOCATIONX = PARSED_PRD.OUTPUTPOSITIONX; // We store the IOPARSE "Output Position X Axis" variable attribute. 
                                                      // !-> (Possible duplicate variable - no reason why...)

  DRAWOUTPUTLOCATIONY = PARSED_PRD.OUTPUTPOSITIONY; // We store the IOPARSE "Output Position Y Axis" variable attribute. 
                                                      // !-> (Possible duplicate variable - no reason why...)

  console.log("Input Parent == ", INPUTREFERENCE);  // DEBUGGING INSTRUCTION :: For confirming that the "source" node is 
                                                    // what it should be when testing. 

  console.log("OUTPUT Parent == ", OUTPUTREFERENCE);  // DEBUGGING INSTRUCTION :: For confirming that the "target" node is 
                                                      // what it should be when testing. 

  const wireNode = document.getElementById("Wire"); // The "master" wire HTML element is fetched from the HTML DOM to be 
                                                    // cloned and have its verticies set. 

  const clone = wireNode.cloneNode(true); // We enable the "master" wire HTML element to be cloned, and store the newly 
                                          // cloned wire line graphic into this variable. 

  document.getElementById("WiredConnection").appendChild(clone); // The HTML clone is then placed neatly into the "canvas"
                                                                 // that is to contain all of the SVG (Scalar Vector Graphics)
                                                                 // that represent the "wires" / "lines" that connect two 
                                                                 // Logic Gate objects together. 

  var wireName = "Wire" + connectionsInitialised; // A unique ID is generated for the wire clone, similar to the Logic Gate 
                                                  // objects or the Logic Gate IO Pins. Although, the integer value appended 
                                                  // afterwards correlates to the exact index in the "jsonSaveWorkspace" 
                                                  // container that matches the exact Logic Gate object connection it is 
                                                  // supposed to represent. 

  console.log(wireName);  // DEBUGGING INSTRUCTION :: For telling me that the unique ID that is associated with the HTML path 
                          // is correct and accessible by other functions too. 

  clone.setAttribute("id", wireName); // We then get the generated wire name and assign it to the "ID" tag attached natively 
                                      // to the HTML path. 

  const ConnectionLine = document.getElementById(wireName); // Then, we fetch the clone we have just produced via its newly 
                                                            // assigned unique ID, and store its HTML DOM address reference 
                                                            // inside of this variable here. 

  ConnectionLine.setAttribute("x1", DRAWOUTPUTLOCATIONX); // For the fetched wire connection, we set one of its information 
                                                          // tags for the X-Axis value to be of the parsed IOPARSE parameter 
                                                          // stored earlier. 
                                                            // This is not for setting the position / size / shape of the 
                                                            // visual wire, but to provide readable and contained data that 
                                                            // other functions can access if necessary, which is much 
                                                            // better than trying to find the value in the phrase 
                                                            // "M 550 710 L 650 330", as seen below. 

  ConnectionLine.setAttribute("y1", DRAWOUTPUTLOCATIONY); // For the fetched wire connection, we set one of its information 
                                                          // tags for the Y-Axis value to be of the parsed IOPARSE parameter 
                                                          // stored earlier. 
                                                            // Stated above, this is NOT to set the position of one of the 
                                                            // wire verticies, but to attach information to it for future 
                                                            // functions to utilise. 

  ConnectionLine.setAttribute("x2", DRAWINPUTLOCATIONX);  // For the fetched wire connection, we set one of its information 
                                                          // tags for the X-Axis value to be of the parsed IOPARSE parameter 
                                                          // stored earlier. 
                                                            // Stated above, this is NOT to set the position of one of the 
                                                            // wire verticies, but to attach information to it for future 
                                                            // functions to utilise. 

  ConnectionLine.setAttribute("y2", DRAWINPUTLOCATIONY);  // For the fetched wire connection, we set one of its information 
                                                          // tags for the Y-Axis value to be of the parsed IOPARSE parameter 
                                                          // stored earlier. 
                                                            // Stated above, this is NOT to set the position of one of the 
                                                            // wire verticies, but to attach information to it for future 
                                                            // functions to utilise. 

  wirePathLine = 
  `M ${DRAWINPUTLOCATIONX} ${DRAWINPUTLOCATIONY} 
  L ${DRAWOUTPUTLOCATIONX} ${DRAWOUTPUTLOCATIONY}`; // The actual path data that the SVG Line will run across is generated 
                                                    // here, and sets each vertex of the line to the specific X and Y values 
                                                    // that it should be associated with. 

  ConnectionLine.setAttribute("d", wirePathLine); // The data path of the visual wire is set to be the generated and formatted 
                                                  // path seen above. 

  ConnectionLine.setAttribute("PairedData", connectionsInitialised); // The integer value of the connectionsInitialised
                                                                     // correlates to the exact index in the "jsonSaveWorkspace" 
                                                                     // container that matches the exact Logic Gate object 
                                                                     // connection it is supposed to represent, allowing future 
                                                                     // functions (like the click to delete the wire function) 
                                                                     // know what connection to delete to prevent erroneous 
                                                                     // simulation in the Workspace. 
                                                                    
  clone.style.display = "block"; // The wire line visual connection is styled to be displayed as a "Box". This means that the 
                                 // hitbox around it is defined by the extent at which the verticies of the wire line go. 
  
  connectionsInitialised++; // The connections initialised are incremented so that the next connection created between two 
                            // objects corresponds to the actual correct "jsonSaveWorkspace" index too. 

  console.log("Parsed PRD Values == ",
    DRAWINPUTLOCATIONX, 
    DRAWINPUTLOCATIONY, 
    DRAWOUTPUTLOCATIONX, 
    DRAWOUTPUTLOCATIONY); // DEBUGGING INSTRUCTION :: For checking that the positions of the IO Pins has been 
                          // successfully parsed into "initConnect()" and that it is in the correct order. 

  jsonReadWrite(  // The function that is needed to handle the backend of the connections between Logic Gates 
                  // is called for the pair being operated on. The same parameters that are used in this function 
                  // are parsed into the backend so that said function has the exact same data to operate on, which 
                  // its critical.

    MODE, // This is a redundant feature that is not necessary, yet is kept to prevent any possible bugs popping up 
          // that is may prevent. 

    INPUTREFERENCE,       // This correlates to the IOPARSE variable attribute seen above. 
    OUTPUTREFERENCE,      // This correlates to the IOPARSE variable attribute seen above. 

    INPUTREFLOCATIONX,    // This correlates to the IOPARSE variable attribute seen above. 
    INPUTREFLOCATIONY,    // This correlates to the IOPARSE variable attribute seen above. 
    OUTPUTREFLOCATIONX,   // This correlates to the IOPARSE variable attribute seen above. 
    OUTPUTREFLOCATIONY,   // This correlates to the IOPARSE variable attribute seen above. 

    GATEREFERENCE_I,      // This correlates to the IOPARSE variable attribute seen above. 
    GATEREFERENCE_O,      // This correlates to the IOPARSE variable attribute seen above. 

    DRAWINPUTLOCATIONX,   // This correlates to the IOPARSE variable attribute seen above. 
    DRAWINPUTLOCATIONY,   // This correlates to the IOPARSE variable attribute seen above. 
    DRAWOUTPUTLOCATIONX,  // This correlates to the IOPARSE variable attribute seen above. 
    DRAWOUTPUTLOCATIONY,  // This correlates to the IOPARSE variable attribute seen above. 

    itemsCreated,         // This is a completely new variable that is parsed into the 
                          // jsonReadWrite function that may come in handy for functions 
                          // that my find this data relevant (e.g. the Save and Loading 
                          // system etc.). 

    INPUTTYPE,            // This correlates to the IOPARSE variable attribute seen above. 
    OUTPUTTYPE,           // This correlates to the IOPARSE variable attribute seen above. 

    INPUTID,              // This correlates to the IOPARSE variable attribute seen above. 
    OUTPUTID              // This correlates to the IOPARSE variable attribute seen above. 

  );  // The amount of parameters parsed into the backend connection handler ends here. 

};  // The function for the visual frontend display of wire line connections between newly initiated 
    // Logic Gate object pairs ends here. 



// *** SCRIPT 016 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 017 *** -- Starts here 
// The purpose of the below code is to give the end user the ability to interact with a visual wire line 
// connection between objects by clicking on it, and then permenantly deleting said wire from the frontend 
// and backend when the end user has successfully clicked / interacted on it. 



const wireContainerReference = document.getElementById('WiredConnection');  // The SVG canvas that contains all 
                                                                            // of the visual wire line connection 
                                                                            // drawings that go between the Logic 
                                                                            // Gate Objects' pins, so we store it 
                                                                            // in here to access it later on. 

wireContainerReference.addEventListener('click', (event) => { // We add an event listener to the Wire Line SVG Canvas 
                                                              // (the Workspace essentially, as it covers the entire 
                                                              // Workspace background), and tell it to fire the 
                                                              // instructions below whenever it is "clicked". 

  const isRestNull = jsonSaveWorkspace.slice(1).every(item => item === null); // This variable holds the 
                                                                              // "jsonSaveWorkspace" variable 
                                                                              // EXCLUDING all indexes with the 
                                                                              // contents "null". 
                                                                              // This is because when a connection 
                                                                              // between objects is deleted, it 
                                                                              // replaces the data about the connection 
                                                                              // in the "jsonSaveWorkspace" with "null".
                                                                              // Hence, we need to remove all "null"'s 
                                                                              // from the jsonSaveWorkspace temporarily
                                                                              // so that there are no "accessed none" 
                                                                              // errors which can halt the program. 

  const clickedElement = event.target;  // We store the HTML element that was just clicked inside of the SVG Canvas 
                                        // (which covers the entire Workspace) inside of this variable here. 

  console.log(clickedElement);  // DEBUGGING INSTRUCTION :: For telling me that a unique wire reference has been 
                                // clicked on and that a wire line HTML element should no longer exist in the 
                                // HTML DOM structure anymore. 

  if (clickedElement.id && clickedElement.id.startsWith("Wire") && simulate != true) {  // We then check if the element 
                                                                                        // that was just clicked exists, 
                                                                                        // and if it is a Wire element, 
                                                                                        // and if the Workspace is NOT 
                                                                                        // simulating. 
                                                                                          // Because we styled the SVG 
                                                                                          // Canvas element to only 
                                                                                          // accept "pointer events"
                                                                                          // when the end user clicks 
                                                                                          // on a Javascript Pen graphic, 
                                                                                          // we shouldn't *need* to check 
                                                                                          // if it is a wire, but this is 
                                                                                          // just for extra safety and 
                                                                                          // validation. 

    console.log("A wire was clicked!", clickedElement.id);  // DEBUGGING INSTRUCTION :: For further confirmation 
                                                            // as to the wire that was clicked. This should tell 
                                                            // me that a wire line should no longer exist with 
                                                            // that specific unique ID in the HTML DOM structure.
    
    clickedElement.setAttribute("stroke", "red"); // DEBUGGING INSTRUCTION :: When the wire line element is clicked, 
                                                  // we set its colour to be "Red" so that I can see that this function 
                                                  // is properly picking up the click event and control flow is reaching 
                                                  // this area. 

    objectPair = clickedElement.getAttribute("PairedData"); // When the end user clicks on the wire element, Simboard must 
                                                            // delete its connection. Therefore, we get the "PairedData" 
                                                            // attribute from the clicked wire line connection, which 
                                                            // matches directly to the "jsonSaveWorkspace" index that
                                                            // stores the necessary backend data for circuit simulation. 

    console.log(objectPair);  // DEBUGGING INSTRUCTION :: For telling me that the "pairedData" number at the end of 
                              // said ID should correlate with the jsonSaveWorkspace index that holds the backend 
                              // connection between two objects. 

    jsonSaveWorkspace[objectPair] = null; // We then visit the jsonSaveWorkspace container variable and change the 
                                          // required index to "null" so that the objects won't relate or simulate 
                                          // together in the Workspace. 

    clickedElement.remove();  // Now that the backend index data has been cleared, we remove the element visually from 
                              // the HTML DOM, essentially deleting the wire and connection between two Logic Gate Objects 
                              // permenantly. 

    presentObjects - 2; // Because the connection has been deleted in the backend and the frontend, two objects have now 
                        // been removed from the total amount of objects Simboard has in its Workspace environment.

    if (isRestNull) { // If the element just clicked was the final connection in the Workspace, and now every single 
                      // index in the "jsonSaveWorkspace" variable container is "null", then we completely clear said 
                      // container to make it easier and faster for other functions to utilise and iterate through it,
                      // instead of passing through 100 "null" indexes, which can get very messy, very fast.  

      jsonSaveWorkspace.length = 0; // To clear the "jsonSaveWorkspace", we set its length to 0 so that it contains 
                                    // nothing and all "null" index values inside of it get wiped permenantly. 

      console.log(jsonSaveWorkspace, " has been emptied!"); // DEBUGGING INSTRUCTION :: For notifying me that there  
                                                            // are no more connections to operate on, so no wire line 
                                                            // can be deleted. 

    } else {  // If every index inside of "jsonSaveWorkspace" does not contain "null", and at least one index contains 
              // actual connection data between two Logic Gate objects, then I want to see what the jsonSaveWorkspace 
              // looks like after a connection has just been removed from said container. 

      console.log("After deletion .. ", jsonSaveWorkspace); // DEBUGGING INSTRUCTION :: For telling me what the 
                                                            // jsonSaveWorkspace connection container looks like now 
                                                            // that the wire line connection has been deleted. 

    };  // The checks for if the "jsonSaveWorkspace" container variable is empty ends here. 

  };  // The validator for if the wire exists and the simulation is not playing ends here. 

}); // The event listener function for when a wire line connection graphic is clicked ends here. 



// *** SCRIPT 017 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 018 *** -- Starts here 
// The purpose of the below code is to take in relevant parameter data about two Logic Gate objects that 
// are connected together, then to organise and set a new, formatted variable that contains said data and 
// then finally package it up into a main container (jsonSaveWorkspace), so that other functions or 
// systems that may need to interact with the Simboard circuit objects can have a robust, and accessible 
// way of doing so. 



function jsonReadWrite( // This function needs a sparse amount of parameters to successfully package 
                        // and push data about two objects being connected, so that other functions 
                        // in Simboard can utilise it (e.g. to simulate a circuit, or to save a circuit 
                        // file etc.). These parameters can be traced back to the IOPARSE variable 
                        // attributes that originate from the "ioCheck()" function. 

  MODE, // This is redundant, and is not needed in this function, but is kept anyway incase something 
        // actually does rely on it. 
  
  CONNECTEDOBJECT_INPUTREF,       // To see what this variable correlates to, check LINE 2879 above. 
  CONNECTEDOBJECT_OUTPUTREF,      // To see what this variable correlates to, check LINE 2880 above. 

  CONNECTEDOBJECT_INPUTREF_POSX,  // To see what this variable correlates to, check LINE 2882 above. 
  CONNECTEDOBJECT_INPUTREF_POSY,  // To see what this variable correlates to, check LINE 2883 above. 
  CONNECTEDOBJECT_OUTPUTREF_POSX, // To see what this variable correlates to, check LINE 2884 above. 
  CONNECTEDOBJECT_OUTPUTREF_POSY, // To see what this variable correlates to, check LINE 2885 above. 

  INPUTBOX,                       // To see what this variable correlates to, check LINE 2887 above. 
  OUTPUTBOX,                      // To see what this variable correlates to, check LINE 2888 above. 

  POSITIONINPUTX,                 // To see what this variable correlates to, check LINE 2890 above. 
  POSITIONINPUTY,                 // To see what this variable correlates to, check LINE 2891 above. 
  POSITIONOUTPUTX,                // To see what this variable correlates to, check LINE 2892 above. 
  POSITIONOUTPUTY,                // To see what this variable correlates to, check LINE 2893 above. 

  NUMOFGATES,                     // To see what this variable correlates to, check LINE 2895 above. 

  INPUTTYPE,                      // To see what this variable correlates to, check LINE 2900 above. 
  OUTPUTTYPE,                     // To see what this variable correlates to, check LINE 2901 above. 

  INPUTUNIQUEID,                  // To see what this variable correlates to, check LINE 2903 above. 
  OUTPUTUNIQUEID                  // To see what this variable correlates to, check LINE 2904 above. 

  ) {

  if (MODE == 0) {  // This is a redundant validator, but it is kept anyway for the reasons 
                    // stated above. 

    const saveFile = {  // A variable is initialised which holds the currently packaged index that 
                        // will be pushed to be contained within the "jsonSaveWorkspace" container 
                        // variable. 

      CONNECTEDOBJECT_A:      CONNECTEDOBJECT_INPUTREF,       // "CONNECTEDOBJECT_A" will be a key inside of the 
                                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                                              // value defined above. 
      CONNECTEDOBJECT_B:      CONNECTEDOBJECT_OUTPUTREF,      // "CONNECTEDOBJECT_B" will be a key inside of the 
                                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                                              // value defined above. 

      INPUTOBJECT_POSX:       CONNECTEDOBJECT_INPUTREF_POSX,  // "INPUTOBJECT_POSX" will be a key inside of the 
                                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                                              // value defined above. 
      INPUTOBJECT_POSY:       CONNECTEDOBJECT_INPUTREF_POSY,  // "INPUTOBJECT_POSY" will be a key inside of the 
                                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                                              // value defined above. 
      OUTPUTOBJECT_POSX:      CONNECTEDOBJECT_OUTPUTREF_POSX, // "OUTPUTOBJECT_POSX" will be a key inside of the 
                                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                                              // value defined above. 
      OUTPUTOBJECT_POSY:      CONNECTEDOBJECT_OUTPUTREF_POSY, // "OUTPUTOBJECT_POSY" will be a key inside of the 
                                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                                              // value defined above. 

      INPUTBOX:               INPUTBOX,       // "INPUTBOX" will be a key inside of the 
                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                              // value defined above. 
      OUTPUTBOX:              OUTPUTBOX,      // "OUTPUTBOX" will be a key inside of the 
                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                              // value defined above. 

      POSITIONINPUTBOXX:      POSITIONINPUTX,       // "POSITIONINPUTBOXX" will be a key inside of the 
                                                    // "jsonSaveWorkspace" index, paired to the parameter 
                                                    // value defined above. 
      POSITIONINPUTBOXY:      POSITIONINPUTY,       // "POSITIONINPUTBOXY" will be a key inside of the 
                                                    // "jsonSaveWorkspace" index, paired to the parameter 
                                                    // value defined above. 
      POSITIONOUTPUTBOXX:     POSITIONOUTPUTX,      // "POSITIONOUTPUTBOXX" will be a key inside of the 
                                                    // "jsonSaveWorkspace" index, paired to the parameter 
                                                    // value defined above. 
      POSITIONOUTPUTBOXY:     POSITIONOUTPUTY,      // "POSITIONOUTPUTBOXY" will be a key inside of the 
                                                    // "jsonSaveWorkspace" index, paired to the parameter 
                                                    // value defined above. 

      NUMOFGATES:             NUMOFGATES,       // "NUMOFGATES" will be a key inside of the 
                                                // "jsonSaveWorkspace" index, paired to the parameter 
                                                // value defined above. 

      CONNECTEDOBJECT_A_TYPE: INPUTTYPE,      // "CONNECTEDOBJECT_A_TYPE" will be a key inside of the 
                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                              // value defined above. 
      CONNECTEDOBJECT_B_TYPE: OUTPUTTYPE,     // "CONNECTEDOBJECT_B_TYPE" will be a key inside of the 
                                              // "jsonSaveWorkspace" index, paired to the parameter 
                                              // value defined above. 

      OBJECTA_INPUTID:        INPUTUNIQUEID,      // "OBJECTA_INPUTID" will be a key inside of the 
                                                  // "jsonSaveWorkspace" index, paired to the parameter 
                                                  // value defined above. 
      OBJECTB_OUTPUTID:       OUTPUTUNIQUEID      // "OBJECTB_OUTPUTID" will be a key inside of the 
                                                  // "jsonSaveWorkspace" index, paired to the parameter 
                                                  // value defined above. 

    };

    console.log(saveFile);  // DEBUGGING INSTRUCTION :: For notifying me what the new jsonSaveWorkspace index 
                            // is formatted like, so  that I can understand any issues with the packaging or 
                            // data itself. 

    jsonSaveWorkspace.push(saveFile); // Said variable that holds the neatly packaged information that will go 
                                      // into the next "jsonSaveWorkspace" index is pushed to the stack. 

    console.log(jsonSaveWorkspace)  // DEBUGGING INSTRUCTION :: For further debugging, this also shows me what the 
                                    // jsonSaveWorkspace container looks like and contains now that a new index has 
                                    // been pushed that contains what is in the "saveFile" variable. 

  } else {  // This branch is redundant, but can act as a debugger if the function is called with the wrong 
            // parameters. 
    
    console.log("No other mode found!")  // DEBUGGING INSTRUCTION :: For notifying me that I may have entered the 
                                         // wrong mode for calling this function. 

  };  // The validation for the redundant mode ends here. 
  
};  // The function for packaging pair data between two Logic Gate objects, and then sending it to the 
    // "jsonSaveWorkspace" container variable ends here. 



// *** SCRIPT 018 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 019 *** -- Starts here 
// The purpose of the below code is to give customised accessbility and output when the end user interacts 
// with the Save Button in Simboards' File Menu. This newfound customisation allows the end user to 
// receive tailored prompts, and outcomes that are appropriate to a saving process when clicking on the 
// Save Button. The end user has the ability to save either Layout Data, or Project Workspace Circuit 
// Data depending on their preference or needs.



getPropertiesSaveButton = document.getElementById("save");  // We fetch the save button from the HTML DOM and store 
                                                            // its address inside of this variable so that we can 
                                                            // access it later on. 

getPropertiesSaveButton.onclick= function() { // We attach an "on click" even listener to the save button, so that 
                                              // the below functions will start whenever the end user clicks on 
                                              // said button. 

  if (simulate != true) { // To ensure that the end user doesn't save a file that is broken due to the simulation 
                          // of a circuit, we ensure that the saving mechanic can only function when the Workspace 
                          // is NOT simulating. 

    TYPE = prompt("Please enter the TYPE of project data you want to save.\nEnter the letter 'L' to save the layout data, and enter\nthe letter 'P' to save your Logic Gate circuit project.\nPress ESC to halt the saving process.");
    // A prompt is to appear for the end user to enter the TYPE of data they want to save to their local disc. This can be 
    // either Layout UI (User Interface) data, or the Circuit Project data with all of their Logic Gate connections. 

    TYPE = TYPE.toUpperCase();  // To avoid any issues with formatting and validation, the letter symbol that the 
                                // end user inputs will be converted to lower case. 

    if (TYPE == 'P') {  // If the end user wants to save their Workspace Circuit Project Data, they must enter the letter 
                        // "P", and if done, control flow will branch into here. 
      
      saveData(0, jsonSaveWorkspace); // The function which handles the download of data is called, with the MODE 
                                      // and the "jsonSaveWorkspace" variable being parsed as parameters. 

      console.log("Saving Simboard Layout Data has been attempted."); // DEBUGGING INSTRUCTION :: For telling me that the saveData 
                                                                      // function was visited, and that Simboard attempted to 
                                                                      // handle it with the jsonSaveWorkspace data container. 

    } else if (TYPE == 'L') {  // If the end user wants to save their User Interface Layout data, they must enter the letter 
                               // "L", and if done, control flow will branch into here. 

      saveData(1, tempStylesContainer); // The function which handles the download of data is called, with the MODE 
                                        // and the "tempStylesContainer" variable attribute container being parsed as 
                                        // parameters. 

      console.log("Saving Simboard Workspace Project Data has been attempted.");  // DEBUGGING INSTRUCTION :: For telling me that 
                                                                                  // the saveData function was visited, and that 
                                                                                  // Simboard attempted to handle it with the 
                                                                                  // tempStylesContainer (POJO) object. 

    } else {  // If the end user enters something that is not either "P" or "L" for saving relevant data, control flow 
              // will branch into here and notify the end user that they may need to enter the correct symbol / character. 

      confirm("Could not understand saving format. Please try again!"); // A simple confirmation box will pop up that 
                                                                        // tells the end user that Simboard won't accept 
                                                                        // symbols other than "P" or "L".
                                                                          // !-> Confirm boxes have "CANCEL" or "OK" response 
                                                                          //     boxes. 

    };  // The validation and control flow branches for the type of data to be saved ends here. 
 
  } else { // If the end user IS simulating their circuit, then control flow will branch into here. 

    alert("You cannot save a Simboard File whilst the Circuits in your Workspace are being simulated!\nPlease stop the simulation to save a Simboard File to your local disc!");
    // A simple alert box with a warning to pause the simulation to save Simboard data pops up for the end user. 
      // !-> Alert boxes have only "OK" as a response. 

    console.warn("You cannot save a Simboard File whilst the Circuits in your Workspace are being simulated!\nPlease stop the simulation to save a Simboard File to your local disc!");
               // DEBUGGING INSTRUCTION ABOVE :: For notifying me about fix kvf

  };  // The validation for preventing the end user from saving Simboard data when the circuit is simulating ends here. 

};  // The function for initiating the saving process when the end user clicks the "Save Button" ends here. 



// *** SCRIPT 019 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 020 *** -- Starts here 
// The purpose of the below code is to give customised accessbility and output when the end user interacts 
// with the Load Button in Simboards' File Menu. This newfound customisation allows the end user to 
// receive tailored prompts, and outcomes that are appropriate to a loading process when clicking on the 
// Load Button. The end user has the ability to drag in a file, and click the Load Button to initiate 
// the required functions that allow Simboard to read and redraw / respawn data from the temporary 
// reserve, into their required and necessary containers or variables.



getPropertiesLoadButton = document.getElementById("load");  // We fetch the load button from the HTML DOM and store 
                                                            // its address inside of this variable so that we can 
                                                            // access it later on. 

getPropertiesLoadButton.onclick= function() { // We attach an "on click" even listener to the load button, so that 
                                              // the below functions will start whenever the end user clicks on 
                                              // said button. 

  if (simulate != true) { // To ensure that the end user doesn't load a file that is broken due to the simulation 
                          // of a circuit, we ensure that the loading mechanic can only function when the Workspace 
                          // is NOT simulating. 

    confirmation = confirm("Remember to save your current project as loading in a new Layout or Project file can override the current Layout or Project data present right now.\nPress CANCEL to halt the loading process until everything is saved.\nPress OK to initialise the loading process.");
    // A quick popup confirmation pops up to notify the end user that loading a Simboard file will overwrite all of 
    // the Layout UI (User Interface) if Layout data is loaded in, or Workspace Circuit Project data if a Circuit Project
    // file has been loaded in. 

    if (importedFileType == 0) {  // If SCRIPT 025 / "loadData()" reads the dragged and dropped Simboard save file header 
                                  // to have a file type of "0", then Simboard should prepare to load in a Logic Gate 
                                  // file for the Workspace. 

      if (confirmation == true && jsonSaveWorkspaceOverwrite.every(item => item !== null)) {  // The "loadData()" function 
                                                                                              // should handle the temporary 
                                                                                              // reserves, and so when control 
                                                                                              // flow reaches here, we must first 
                                                                                              // see if the end user wants to 
                                                                                              // overwrite their circuit project 
                                                                                              // data, and if the save file 
                                                                                              // imported actually contains 
                                                                                              // some form of connection data, 
                                                                                              // as to not get "accessed none"
                                                                                              // errors when operating on 
                                                                                              // "null" indexes.  

        stopLoadGif();  // The little loading animation playing on the Load Button when the end user drags a file onto 
                        // it will stop when the Load Button is clicked, resolving the promise defined when started.  

        clearWorkspace(); // All data in the frontend and backend relating to the Workspace or simulation is fully wiped
                          // and cleared for this new Logic Gate circuit(s) to spawn in. 

        redrawImport(0);  // All logic gates present in the jsonSaveWorkspace temporary reserve (jsonSaveWorkspaceOverwrite)
                          // are summoned back onto the Workspace. 

      } else {  // If there is no data to operate on in the imported circuit project save file, or if the end user cancels 
                // the operation, then control flow branches into here. 

        alert("No file was found in the temporary reserve!\n\nIf a file has been recognised, a little animation will play on the LOAD BUTTON icon, signifying a Simboard JSON file has been loaded into the temporary reserve.\n\nPlease try again!");
        // A simple alert message pops up to notify the end user no data was found, or that the loading operation was 
        // successfully cancelled. 

      };  // The branching for checking if the end user wants to load in the save file, and that the save file isn't 
          // empty ends here. 

    } else if (importedFileType == 1) { // If SCRIPT 025 / "loadData()" reads the dragged and dropped Simboard save file header 
                                        // to have a file type of "1", then Simboard should prepare to load in a Layout UI 
                                        // (User Interface) file for the Workspace. 

      if (confirmation == true && !(Object.keys(tempStylesContainerOverwrite).length === 0)) {  // The "loadData()" function 
                                                                                                // should handle the temporary 
                                                                                                // reserves, and so when control 
                                                                                                // flow reaches here, we must first 
                                                                                                // see if the end user wants to 
                                                                                                // overwrite their current UI 
                                                                                                // configurations and if the save 
                                                                                                // file imported actually contains 
                                                                                                // some form of connection data, 
                                                                                                // as to not get "accessed none"
                                                                                                // errors when operating on 
                                                                                                // "null" indexes. 

      stopLoadGif();  // The little loading animation playing on the Load Button when the end user drags a file onto 
                      // it will stop when the Load Button is clicked, resolving the promise defined when started.  

      redrawImport(1);  // All styling colours in the Layout temporary reserve (tempStylesContainerOverwrite)
                        // are repainted back onto the UI (User Interface) HTML divisions. 

      } else {  // If there is no data to operate on in the imported Layout UI (User Interface) save file, or if the end user 
      // cancels the operation, then control flow branches into here. 

      alert("No file was found in the temporary reserve!\n\nIf a file has been recognised, a little animation will play on the LOAD BUTTON icon, signifying a Simboard JSON file has been loaded into the temporary reserve.\n\nPlease try again!");
        // A simple alert message pops up to notify the end user no data was found, or that the loading operation was 
        // successfully cancelled. 

      };  // The branching for checking if the end user wants to load in the save file, and that the save file isn't 
          // empty ends here. 

    } else {  // Another decision branch should also exist in the case that the "loadData()" function couldn't properly 
              // read the file type in the Simboard save file header, to which the end user should be prompted on quick 
              // fixes that can be taken to recover the file. 

      alert("The loading process was cancelled, most likely because no file has been dragged & dropped into the Workspace or if the Loading Process was terminated / cancelled!\n\n - Please check the details of this outcome in the Console / Developer Console!");
      // As stated, the end user is alerted to the fact that their Simboard save file may be corrupted, and is given 
      // fix methods, like brute forcing the .json file to have a file type of 0 or 1 in the file header when opened 
      // in a text editor, for example. 

      console.warn("There was an error reading your imported file, please try again!\n\nThis could be because your file does not have the 'JSON' file extension, has bypassed some backend validation process, or has been corrupted.\n\nTo fix this, go into your imported file, and change the 'fileFormat' value to a 0 for Workspace Project data, or to a 1 for UI Layout data.");
      // DEBUGGING INSTRUCTION :: Just like the alert above, I must know that the system cannot understand the file that 
      // has been imported via the drag and drop method. 

    };  // The branching for the file type loading ends here. 

  } else {  // Another branch is necessary for alerting the end user that they cannot load data when the Workspace is 
            // simulating a circuit. 

    alert("You cannot load a Simboard File from the temporary reserve whilst the Circuits in your Workspace are being simulated!\nPlease stop the simulation to load a Simboard File from the temporary reserve!"); 
    // A quick alert is given to the end user, notifying them that they cannot proceed with this action when the 
    // Circuit(s) are simulating. 

    console.warn("You cannot load a Simboard File from the temporary reserve whilst the Circuits in your Workspace are being simulated!\nPlease stop the simulation to load a Simboard File from the temporary reserve!");
    // DEBUGGING INSTRUCTION :: The same message is printed / output in the console log, just to notifying me that 
    // control flow has reached this area. 

  };  // The branching for circuit simulation validation ends here. 

};  // The function for loading a Simboard save file when the Load Button is clicked ends here. 



// *** SCRIPT 020 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 021 *** -- Starts here 
// The purpose of the below code is to give visual feedback to the end user when they load in a Simboard 
// save file, by playing a "GIF" animation, hard-coded, on the Load Button HTML image. Although the 
// animation frames are all hand-drawn, to dedicate my time to solving other issues, the decision to code 
// the animation by iterating through frames until the end user clicks on the Load Button is beneficial to 
// the development and time management for the Simboard application, yet may put a tiny strain on the CPU. 



const loadGifContents = [ // This variable holds all of the file references to where each image that will 
                          // make up the GIF is stored. 

  "/Media/GIFFYFrames/F0.png",    // This is frame zero for the GIF animation. 
  "/Media/GIFFYFrames/F1.png",    // This is frame one for the GIF animation. 
  "/Media/GIFFYFrames/F2.png",    // This is frame two for the GIF animation. 
  "/Media/GIFFYFrames/F3.png",    // This is frame three for the GIF animation. 
  "/Media/GIFFYFrames/F4.png",    // This is frame four for the GIF animation. 
  "/Media/GIFFYFrames/F5.png",    // This is frame five for the GIF animation. 
  "/Media/GIFFYFrames/F6.png",    // This is frame six for the GIF animation. 
  "/Media/GIFFYFrames/F7.png",    // This is frame seven for the GIF animation. 
  "/Media/GIFFYFrames/F8.png",    // This is frame eight for the GIF animation. 
  "/Media/GIFFYFrames/F9.png",    // This is frame nine for the GIF animation. 
  "/Media/GIFFYFrames/F10.png",   // This is frame ten for the GIF animation. 
  "/Media/GIFFYFrames/F11.png",   // This is frame eleven for the GIF animation. 
  "/Media/GIFFYFrames/F12.png",   // This is frame twelve for the GIF animation. 
  "/Media/GIFFYFrames/F13.png",   // This is frame thirteen for the GIF animation. 
  "/Media/GIFFYFrames/F14.png"    // This is frame fourteen for the GIF animation. 

];  // In total, there are fifteen (15) frames that will make up the Loading animation present on the Load Button 
    // when the end user drags and drops a file into the Simboard web application. 

currentAnimFrame = 0;   // This variable will hold the current GIF frame that the load button will have 
                        // present on it. 

frameRate = null;   // This variable is defined to be null to start with, yet it will contain a promise 
                    // later on that will be resolved when the end user clicks on the Load Button. 
                      // This promise will be for playing the actual GIF animation on the Load Button. 

blinkRate = null;  // This variable is defined to be null to start with, yet it will contain a promise 
                   // later on that will be resolved when the end user clicks on the Load Button. 
                    // This promsie will be for playing a blinking effect behind the GIF animation 
                    // on the Load Button. 

animDelay = 215; // This variable holds the time interval between frames in milliseconds. Because I want 
                 // my GIF to be ~3 frames per second, the interval should be ~215 (ms) per frame present 
                 // on the Load Button. 

blinkDelay = 1500;  // This variable holds the time interval between blinks in milliseconds. Because I want 
                    // there to be a ~1.5 second delay between blinks, I set this variable to be ~1500 (ms)
                    // to do this. 

loadButtonIcon = document.getElementById("load").children[1]; // To get the image container inside of the 
                                                              // Load Button, the Load Buttons' HTML child 
                                                              // element must be fetched that contains it, 
                                                              // so the GIF has a place to play.  

loadButtonBackgroundRef = document.getElementById("load");  // The Load Button itself is fetched too, so t
                                                            // that a blinking effect can play behind the 
                                                            // GIF. 

function playLoadGif() {  // The function that starts the GIF animation and the blinking effect starts here. 

  frameRate = setInterval(() => { // A "setInterval" promise is set, which is stored in the "frameRate" 
                                  // global variable. This is done so that the interval can clear itself 
                                  // when the GIF needs to stop. 

      loadButtonIcon.setAttribute("src", loadGifContents[currentAnimFrame]);  // The default LOAD image on 
                                                                              // the Load Buton should be 
                                                                              // replaced with the index 
                                                                              // of the current frame of 
                                                                              // our GIF that we want to 
                                                                              // play on it, starting at 
                                                                              // index 0 in the container 
                                                                              // "loadGifContents"

      currentAnimFrame = (currentAnimFrame + 1) % loadGifContents.length; // The current frame to display 
                                                                          // for the GIF is incremented so 
                                                                          // that the animation plays in 
                                                                          // a linear manner, yet if the 
                                                                          // incrementation is trying to 
                                                                          // display a GIF frame that is 
                                                                          // more than what is provided 
                                                                          // then it will return to frame 
                                                                          // zero, effectively achieving 
                                                                          // a "looping" GIF animation.

      if (currentAnimFrame % 4 === 0) { // Every four GIF frames, a "blink" effect will appear behind the 
                                        // GIF animation on the Load Buttons' background, using the same 
                                        // MOD (Modulo / %) logic seen above in the previous instruction. 

        loadButtonBackgroundRef.style.opacity = (loadButtonBackgroundRef.style.opacity == "0.9") ? "1" : "0.9";
        // To achieve this blinking effect, we ensure the opacity of the background becomes duller, allowing 
        // the end user to visually see an apparent "blink" every set period. 
        // This is done by using a ternary operator (?) to flip the opacity value between "0.9" and "1" every 
        // four frames. 

      };  // The blinking effect loop will end here, and repeat until the "frameRate" promise is resolved. 

  }, animDelay);  // This entire loop is repeated every 215 milliseconds (ms) defined in the variable above. 

};  // The function to play the GIF via a promise on the Load Button when called ends here. 



// *** SCRIPT 021 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 022 *** -- Starts here 
// The purpose of the below code is to stop the loading "GIF" animation that plays on the Load Button when 
// the end user clicks on said button to reimport the Save File data. This creates a responsive feedback 
// system so that the end user can know that their save data has been fully handled to the extent coded in 
// Simboard. 



function stopLoadGif() {  // The function to end the loading GIF promise starts here. 

  clearInterval(frameRate)  // To stop the GIF from playing, because it is done in a "promise", 
                            // we simply clear the promise to tell the Browser that the function 
                            // that plays the loading animation should stop in its tracks and 
                            // cache itself. 

  document.getElementById("load").children[1].setAttribute("src", "/Media/Layout/LoadProject.png");
  // To solve the problem of the "stuck frame" where the Load Button picture would display the 
  // last frame of the GIF animation when stopped, we simply tell the HTML button child element 
  // to display the default "load" picture to overwrite the recent GIF frame.

  loadButtonBackgroundRef.style.opacity = "1";  // To solve the blinking effect, the load buttons' 
                                                // opacity is forced back to being "solid" and 
                                                // not transparent slightly, via the value "1". 

};  // The function that stops the GIF frame from playing on the load button ends here. 



// *** SCRIPT 022 *** -- Ends here 
