//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 026 *** -- Starts here 
// The purpose of the below code is to completely wipe all of the visual elements inside of the Workspace, 
// including HTML Logic Gate objects and HTML Paths / Wires that connect two objects together, and 
// excluding the actual Workspace visuals (e.g. the Grid and Axies) permenantly. The purpose of this is 
// to provide a fresh start to Simboard, which is useful when new data has been fully imported, preventing 
// confusing and clogging of other functions, especially those to do with simulation or object connection 
// pairing. This can also be used if the end user doesn't want to manually delete multiple objects and or 
// connections in the Workspace (done in the Talk To System function). 



function clearWorkspace () {  // The function for handling the clearing and wiping of elements and 
                              // relevant data to the Workspace and other functions starts here. 

  console.clear();  // Firstly, for my and any other developer who sees this's benefit, the console 
                    // may wish to be cleared due to the pile-up of non-relevant debug information 
                    // which heavily accumulates over time. 

  const oldCircuitObjectsToDelete = document.querySelectorAll('div[tag^="interactableObject"]');
  // Every single Logic Gate Object, which is built from a HTML Division (div tag), is collected 
  // and stored inside of the variable seen above. 

  const oldCircuitWireLinesToDelete = document.querySelectorAll('path[tag^="interactableObject"]');
  // Every single Connection Path wire line that visually connects two Logic Gate Objects togethe, 
  // which is built from a HTML Path (path tag), is collected and stored inside of the variable 
  // seen above. 

  oldCircuitObjectsToDelete.forEach(elm => {  // We first iterate through each Logic Gate Object 
                                              // collected inside of the garbage collection 
                                              // variable, and visit its reference in the HTML 
                                              // DOM structure. 

    if (elm.id != "mydiv") {  // To avoid deleting the master Logic Gate Object, which is where 
                              // every spawned Logic Gate object is built / cloned from, we tell 
                              // Simboard to not delete any HTML element with an "ID" tag that 
                              // contains the string "mydiv". 

      console.log("Erased ", elm.getAttribute("gatetype"), " from the Workspace!"); // DEBUGGING INSTRUCTION :: For telling 
                                                                                    // me the type of Logic Gate that was 
                                                                                    // deleted from the Workspace, just 
                                                                                    // for confirmation!

      elm.remove(); // Each element inside of "oldCircuitObjectsToDelete" is deleted permenantly 
                    // from the HTML DOM, aside from the master Logic Gate Object. 

    } else {  // If the Logic Gate Object being visited currently IS the master Logic Gate 
              // Object, then control flow branches into here. 

      console.warn("Safety lock prevented deletion of master gate or master wire line!"); // DEBUGGING INSTRUCTION :: For 
                                                                                          // notifying me that the Master 
                                                                                          // Logic Gate Object has not 
                                                                                          // been deleted, confirming that 
                                                                                          // this mechanic is working 
                                                                                          // as intended.

    };  // The validation branch to ensure the master Logic Gate Object does not get deleted ends here. 

  }); // The loop that iterates through each Logic Gate Object HTML DOM reference stored inside of the 
      // "oldCircuitObjectsToDelete" variable ends here. 

  oldCircuitWireLinesToDelete.forEach(el => { // We first iterate through each SVG (Scalar Vector 
                                              // (Graphics) Canvas Path collected inside of the 
                                              // garbage collection variable, and visit its 
                                              // reference in the HTML DOM structure. 

    if (el.id != "Wire") {  // To avoid deleting the master SVG Wire Line, which is where 
                            // every spawned Wire Line is built / cloned from, we tell Simboard 
                            // to not delete any SVG Wire Line with an "ID" tag that contains 
                            // the string "Wire". 

      console.log("Erased ", el.id, " from the Workspace!"); // DEBUGGING INSTRUCTION :: For telling 
                                                             // me the type of Logic Gate that was 
                                                             // deleted from the Workspace, just 
                                                             // for confirmation!

      el.remove(); // Each element inside of "oldCircuitWireLinesToDelete" is deleted permenantly 
                   // from the HTML DOM, aside from the master SVG Wire Line. 

    } else {  // If the SVG Wire Line being visited currently IS the master Wire Line / 
              // HTML Path, then control flow branches into here. 

      console.warn("Safety lock prevented deletion of master wire line!");  // DEBUGGING INSTRUCTION :: For 
                                                                            // notifying me that the Master 
                                                                            // SVG Wire Line / Path has not 
                                                                            // been deleted, confirming that 
                                                                            // this mechanic is working 
                                                                            // as intended.

    };  // The validation branch to ensure the master SVG Wire Line does not get deleted ends here. 

  }); // The loop that iterates through each SVG Wire Line / Path HTML DOM reference stored inside of the 
      // "oldCircuitWireLinesToDelete" variable ends here. 

  jsonSaveWorkspace = [];   // For extra robustness, the "jsonSaveWorkspace" container is cleared to avoid 
                            // future errors. 

  PREVIOUSIOSTACK = [];     // For extra robustness, the "PREVIOUSIOSTACK" container is cleared to avoid 
                            // future errors. 

  PREVIOUSIO = [];    // For extra robustness, the "PREVIOUSIO" container is cleared to avoid 
                      // future errors. 

  hasFirstIOBeenSelected = false;   // For extra robustness, the "hasFirstIOBeenSelected" variable is cleared to avoid 
                                    // future errors. 

  hasSecondIOBeenSelected = false;    // For extra robustness, the "hasSecondIOBeenSelected" variable is cleared to avoid 
                                      // future errors. 

  IOPOSITIONSTACK = [];   // For extra robustness, the "IOPOSITIONSTACK" container is cleared to avoid 
                          // future errors. 

  DRAWBOXSTACK = [];  // For extra robustness, the "DRAWBOXSTACK" container is cleared to avoid 
                      // future errors. 

  IOPARSE = [];   // For extra robustness, the "IOPARSE" container is cleared to avoid 
                  // future errors. 

  IOPARSE.INPUTPOSITIONX = 0;   // For extra robustness, the "IOPARSE.INPUTPOSITIONX" attribute is cleared to avoid 
                                // future errors. 

  IOPARSE.INPUTPOSITIONY = 0;   // For extra robustness, the "IOPARSE.INPUTPOSITIONY" attribute is cleared to avoid 
                                // future errors. 

  IOPARSE.OUTPUTPOSITIONX = 0;  // For extra robustness, the "IOPARSE.OUTPUTPOSITIONX" attribute is cleared to avoid 
                                // future errors. 

  IOPARSE.OUTPUTPOSITIONY = 0;    // For extra robustness, the "IOPARSE.OUTPUTPOSITIONY" attribute is cleared to avoid 
                                  // future errors. 

  IOPARSE.INPUT = null;      // For extra robustness, the "IOPARSE.INPUT" attribute is cleared to avoid 
                            // future errors. 

  IOPARSE.OUTPUT = null;    // For extra robustness, the "IOPARSE.OUTPUT" attribute is cleared to avoid 
                            // future errors. 

  gatePositionXGlobalReference = 0;   // For extra robustness, the "gatePositionXGlobalReference" variable is cleared to 
                                      // avoid future errors. 

  gatePositionYGlobalReference = 0;   // For extra robustness, the "gatePositionYGlobalReference" variable is cleared to 
                                      // avoid future errors. 

  selectedGatesStack = [];  // For extra robustness, the "selectedGatesStack" container is cleared to avoid 
                            // future errors. 

  totalSelectedGates = 0;   // For extra robustness, the "totalSelectedGates" variable is cleared to avoid 
                            // future errors. 

};  // The function that clears the entire Workspace from all data for other functions to benefit from ends here. 



