//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 027 *** -- Starts here 
// The purpose of the below code is to generate a new, more practical Hexadecimal (HEX) colour string from 
// more user-friendly HTML colouring strings like RGB (Red Green Blue). This is because HEX is universally 
// understood in any JavaScript function in this program, unlike complicated strings. This is utilised in 
// the dragging of files into the Workspace, where the background turns to the opposite of the actual 
// background to provide user feedback. Because HTML uses more complex colouring schemes, like 
// "rgb(214, 82, 67)", using more practical and simple strings like "#F4E7AA" are much better for 
// JavaScript to work with in an efficient, immediate and effective way.



function rgbToHexadec(rgb) {  // To convert an RGB (Red Green Blue) value into a JavaScript-readable 
                              // HEX (Hexadecimal) code, a valid RGB value needs to be parsed in. 
                                // RGB Example: rgb(253, 19, 55)
                                // HEX Example: #9C33E4
                              // HEX values are easier and more efficient to operate on for 
                              // the JavaScript functions present in this program document. 

  const rgbValues = rgb.match(/\d+/g);  // This variable holds all of the digits inside of the 
                                        // parsed RGB colour string, excluding all brackets 
                                        // and commas and symbols / characters. 
                                          // This is done by checking and then bookmarking 
                                          // (with /) each digit (with \d), then collects 
                                          // them each as 3 Signficant Figure pairs 
                                          // (seperated by the R, G and B characters with 
                                          // +), and finally  checks the entire RGB string 
                                          // (with /g) until the colour string is fully 
                                          // checked. 
  
  if (!rgbValues || rgbValues.length < 3) { // If there was nothing found in the parsed RGB 
                                            // string, or either the RED, GREEN or BLUE 
                                            // 3 digit values aren't found, then control 
                                            // flow will branch into here, since the parsed 
                                            // value is erroneous and unhealthy. 

    return "#FFFFFF"; // As a default fallback, we return a pitch white colour to signify 
                        // that an error has occurred. 

  } else {  // Yet, if the parsed RGB colour string is healthy and contains seperate RED, 
            // GREEN and BLUE colour values done by the variable operation above, then 
            // control flow branches into here. 

    const r = parseInt(rgbValues[0]).toString(16).padStart(2, '0'); // For the Red value (r), 
                                                                    // we convert it into a 
                                                                    // number formatted value
                                                                    // with the parseInt 
                                                                    // instruction, and then 
                                                                    // convert said number 
                                                                    // value into Hexadecimal 
                                                                    // format with the toString(16) 
                                                                    // instruction. Finally, to 
                                                                    // ensure that the RED value 
                                                                    // is formatted to a HEX digit, 
                                                                    // we tell it to be 2 characters 
                                                                    // long if it isn't already. 
                                                                      // !-> E.g. C -> 0C

    const g = parseInt(rgbValues[1]).toString(16).padStart(2, '0'); // For the Green value (g), 
                                                                    // we convert it into a 
                                                                    // number formatted value
                                                                    // with the parseInt 
                                                                    // instruction, and then 
                                                                    // convert said number 
                                                                    // value into Hexadecimal 
                                                                    // format with the toString(16) 
                                                                    // instruction. Finally, to 
                                                                    // ensure that the GREEN value 
                                                                    // is formatted to a HEX digit, 
                                                                    // we tell it to be 2 characters 
                                                                    // long if it isn't already. 
                                                                      // !-> E.g. C -> 0C

    const b = parseInt(rgbValues[2]).toString(16).padStart(2, '0'); // For the Blue value (b), 
                                                                    // we convert it into a 
                                                                    // number formatted value
                                                                    // with the parseInt 
                                                                    // instruction, and then 
                                                                    // convert said number 
                                                                    // value into Hexadecimal 
                                                                    // format with the toString(16) 
                                                                    // instruction. Finally, to 
                                                                    // ensure that the BLUE value 
                                                                    // is formatted to a HEX digit, 
                                                                    // we tell it to be 2 characters 
                                                                    // long if it isn't already. 
                                                                      // !-> E.g. C -> 0C

    return `#${r}${g}${b}`; // Finally, the RED, GREEN and BLUE HEX digits are concatonated and 
                            // glued together to be returned as the converted RGB to HEX colour 
                            // string. 

  };  // The validation check for if the RGB value is valid or not ends here. 

};  // The function for converting an RBG colour string into a HEX colour string ends here. 



// *** SCRIPT 027 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 028 *** -- Starts here 
// The purpose of the below code is to take a colour string parameter, and then calculate its opposite 
// colour on the Colour Wheel. This is especially useful in the dragging and dropping files to load 
// them into Simboard function, where the opposite colour of the Workspace background is needed when 
// a file is "hovering" over it. This accounts for any customisation changes that the end user may have 
// made to the Simboard UI, so that this specific user feedback is very visible. The inversion is done 
// by stripping away its "HEX" status, splitting the string into RED, GREEN and BLUE, and then  
// finding the opposite colour by subtracting it from 255 (the colour value limit in modern systems). 
// Finally, the string is re-assembled and returned as a fully packaged and newly inverted "colour 
// string".



function getInvertedColour(hexValue) {  // This function, in order to return an opposite HEX 
                                        // colour string, needs to have a HEX colour string 
                                        // in the first place. This HEX value is taken as a 
                                        // parameter for this function. 

    hexValue = hexValue.replace('#', ''); // The starting HEX identifier, aka. the Hashtag / 
                                          // Pound Sign / # is removed completely from the 
                                          // HEX string parsed in. 

    let r = parseInt(hexValue.substring(0, 2), 16); // The first two digits of the HEX value 
                                                    // always represent the RED colour part. 
                                                    // Therefore, this is split from the parsed 
                                                    // HEX colour string, and is stored in its 
                                                    // own variable compartment for later use. 

    let g = parseInt(hexValue.substring(2, 4), 16); // The next two digits of the HEX value 
                                                    // always represent the GREEN colour part. 
                                                    // Therefore, this is split from the parsed 
                                                    // HEX colour string, and is stored in its 
                                                    // own variable compartment for later use. 

    let b = parseInt(hexValue.substring(4, 6), 16); // The final two digits of the HEX value 
                                                    // always represent the BLUE colour part. 
                                                    // Therefore, this is split from the parsed 
                                                    // HEX colour string, and is stored in its 
                                                    // own variable compartment for later use. 

    r = (255 - r).toString(16).padStart(2, '0');  // To then convert the colour into its 
                                                  // exact colour wheel opposite, we take 
                                                  // the value of 255 from the numerical 
                                                  // value of the RED Hexadecimal colour 
                                                  // digit. 
                                                    // E.g. if RED has an intensity of 255, 
                                                    //      then its opposite would be 
                                                    //      very dark (aka. 0). 
                                                    // E.g. if RED has an intensity of 0, 
                                                    //      then its opposite would be 
                                                    //      very intense (aka. 255).

    g = (255 - g).toString(16).padStart(2, '0');  // To then convert the colour into its 
                                                  // exact colour wheel opposite, we take 
                                                  // the value of 255 from the numerical 
                                                  // value of the GREEN Hexadecimal colour 
                                                  // digit. 

    b = (255 - b).toString(16).padStart(2, '0');  // To then convert the colour into its 
                                                  // exact colour wheel opposite, we take 
                                                  // the value of 255 from the numerical 
                                                  // value of the BLUE Hexadecimal colour 
                                                  // digit. 

    return `#${r}${g}${b}`; // We then return the final, exact colour-wheel-opposite HEX 
                            // value to wherever it is called via concatonation with 
                            // the values themselves, and the original hashtag / pound 
                            // sign so that it is properly formatted as a HEX colour 
                            // string. 

};  // The function for inverting a HEX (Hexadecimal) colour string ends here. 



