// *** SCRIPT 029 *** -- Starts here 
// The purpose of the below code is to add an event listener for when the end user "drags" something over 
// the Simboard application window in the Browser, which can be either another application window, to an 
// image, to a link, to a file. While this occurs, the Workspace colour will be the "inverted" (opposite 
// on the Colour Wheel) colour that it once was. This allows for neat user feedback, as even if the end 
// user customises their Simboard User Interface (UI), they will still be able to clearly see the user 
// feedback explained earlier, giving them the undrstanding that files can be dragged and dropped into 
// the Workspace to be reimported then loaded, and that Simboard is receiving it loud and clear!



const WorkspaceRef = document.getElementById("Base"); // To start with, the Baseplate for the entire 
                                                      // Simboard application (visually) is stored 
                                                      // as a reference inside of this variable, so 
                                                      // that it can be accessed later on. 

let computedRGB = window.getComputedStyle(GridCanvasColour).backgroundColor;  // The exact colour that 
                                                                              // the Workspace displays  
                                                                              // in the Background is 
                                                                              // fetched.

let currentHex = rgbToHexadec(computedRGB); // We then convert that exact, CSS-precise colour string 
                                            // that is an RGB value, into a Hexadecimal (HEX) value
                                            // so that it is easier, more efficient and more 
                                            // JavaScript-friendly for this function to process and 
                                            // utilise, and store said HEX value inside of this 
                                            // global variable. 

WorkspaceRef.addEventListener("dragover", (e) => {  // When the end user drags anything from a Window, 
                                                    // to a Link, to a File over the Simboards' "Base", 
                                                    // this event listener will fire control flow into 
                                                    // the instructions below. 

  e.preventDefault(); // This instruction prevents the Browser from opening the file or object that 
                      // was dragged and dropped into the Simboard application in a new tab, and 
                      // instead tells the Browser that the file will be handled by the functions  
                      // built into Simboard. 

  GridCanvasColour.style.backgroundColor = getInvertedColour(tempStylesContainer.tempCanvasColour); 
  // The instruction above tells the Workspace background to appear as the complete and exact 
  // "opposite" colour to the one that is displaying currently. 
  // !-> This accounts for any customisations that the end user may have made to change the colour 
  //     of the Workspace background, so that the drag and drop effect / mechanic is visible to any 
  //     UI (User Interface) customisation! 

}); // The function for detecting the "drag" of objects over the Simboard web application ends here. 



