//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 033 *** -- Starts here 
// The purpose of the below code is to give customised accessbility and output when the end user interacts 
// with the Line Solver Button in Simboards' File Menu. This newfound customisation allows the end user to 
// receive tailored prompts, and outcomes that are appropriate to configuring the wire line connections 
// between objects in the current Workspace project. The end user has the ability to call SCRIPT 034, aka. 
// "lineSolver()"" with a whole integer value to represent the mode to use. This gives the end user the 
// ability to colour, manipulate, style or fix the wire line visual connections at their own will. This 
// function is critical, and can manipulate the HTML paths (UI) that visually connect two objects together, 
// for a better UX (User Experience). 



LineSolverButtonLink = document.getElementById("lineSolver"); // The "line solver" button from the Simboard File Menu is 
                                                              // fetched from the HTML DOM Structure, and its reference 
                                                              // address is stored inside of this variable here. 

LineSolverButtonLink.onclick= function() {  // An event listener function is attached to the "Line Solver" button, and 
                                            // whenever it detects that the end user has clicked on said button, control 
                                            // flow goes into the instructions below. 

  if (simulate != true) { // We must ensure that the end user cannot use this mechanic in Simboard when the circuit is 
                          // simulating, in order to avoid errors or points of failure when intensive functions like 
                          // "discernBoolean()" are operating at the same time. 

    solverMode = prompt("Please enter a number to determine the Line Solver Mode! The various integers you can input include:\n\n0 - All current wires become Linear\n1 - All current wires become Orthogonal\n2 - All current wires become Curved\n3 - Change the transparency of all current wires\n4 - Fix all wire positions\n5 - Change the colours of all current wires\n6 - Change the thickness of all current wires"); 
    // The end user is given a choice of mode when using the "Line Solver". To do this, they must enter an integer 
    // number to use said mode. 
    // The various modes and what they do are also included in this prompt to give the end user an idea of what they 
    // might like to utilise. 

    if (solverMode > -1 && solverMode < 7) {  // A simple validation check is done to ensure that the end user actually 
                                              // entered a mode (between and including 0 and 6) into the prompt that exists, 
                                              // otherwise the "Line Solver" may return an unexpected error. 

      console.log(solverMode);  // DEBUGGING INSTRUCTION :: For confirming to me that I have indeed entered the correct line 
                                // solver mode into the line solver function prompt.

      lineSolver(Math.round(solverMode)); // In the rare case that the end user or a developer tries to stress test this system, 
                                          // the "float / real" value that they may have entered is rounded to the nearest 
                                          // whole number to avoid unexpected errors when using the "Line Solver". 

    } else {  // If the end user enters a mode that is not in the range provided, then control flow will branch into the 
              // instructions below. 

      alert("You must enter a number to determine the Line Solver mode!");  // The end user is given a simple prompt which 
                                                                            // notifies them that they entered an incorrect 
                                                                            // mode, and to try again by using the menu / 
                                                                            // catalouge of "Line Solver" modes provided. 

      console.warn("You must enter a number to determine the Line Solver mode!"); // In the developer tools, I should be notified 
                                                                                  // inside of the console log that control flow 
                                                                                  // has reached this branch for debugging purposes. 

    };  // The validator branches for if the end user enters a correct "Line Solver" mode into the prompt ends here. 

  } else {  // If the end user is simulating a circuit, and the end user wants to use the "Line Solver" function, then control 
            // flow goes into the instruction(s) below. 

    alert("You cannot change the Line Solver mode whilst the Circuits in your Workspace are being simulated!\nPlease stop the simulation to change the Connection Line Solver!");
    // A quick alert is given to the end user, notifying them that they cannot proceed with this action when the 
    // Circuit(s) are simulating. 

  };  // The branching for if the end user tries to use the "Line Solver" when simulating a circuit or not ends here. 

};  // The function for paving a way to utilise the "Line Solver" function via a button in the File Menu ends here.   



// *** SCRIPT 033 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 034 *** -- Starts here 
// The purpose of the below code is to shape, manipulate, style or fix the wire line connections between 
// logic gate objects present on the end users' Workspace. This function can be called by the end user 
// when wanting to make their wires curved or coloured for example, or by other functions in the Simboard 
// application that may want to fix the wire connections for example (like the fixVisuals function). This 
// function has varied ability, giving the choice of making all HTML Paths linear, orthogonal or curved by 
// using math to determine point A, the midpoint and then point B, and then setting said paths' data path 
// to said values in that order. There are 7 very unique and artistic modes in this function that can be 
// used at the systems or the end users disposal when necessary!



function lineSolver(MODE) { // This function will take a mode that determines how the visual wire lines between the 
                            // connections should look or be fixed, parsed as a parameter called "MODE", which is to 
                            // be an integer value. 

  solverButtonImageRef = document.getElementById("lineSolver").children[1]; // When the end user changes their line 
                                                                            // solver mode, the actual "Line Solver" 
                                                                            // button must change its display 
                                                                            // thumbnail / image to account for the 
                                                                            // specific "Solver" being used. 

  if (MODE == 0) {  // If this function is called with a "MODE" of 0, then all of the visual wire line connections will 
                    // be styled to be linear. This means that each "wire line" will look like it's going straight from 
                    // "Pin" A to "Pin" B. 

    solverButtonImageRef.setAttribute("src", "/Media/Layout/lineSolverM0.png"); // Simboard immediately changes the Line
                                                                                // Solver button icon to represent the 
                                                                                // "Linear Styling" mode for the visual Wire 
                                                                                // Line connections. 

    lineRef = document.querySelectorAll('path[tag="interactableObject"]'); // All of the visual "wire line" connections 
                                                                           // that visually represent the wiring of 
                                                                           // Logic Gate objects are stored in this 
                                                                           // variable. Because they are all HTML "Path" 
                                                                           // objects, we fetch all "Paths" with the 
                                                                           // attribute "Tag" that contains the string 
                                                                           // "interactableObject" for validation. 

    lineRef.forEach(ConnectionLine => { // To style each visual "wire line" connection in the Workspace, Simboard must 
                                        // iterate through each of said "wire line" HTML references stored in the "lineRef"
                                        // variable. 

      ConnectionLine.style.opacity = "1.0"; // Each wire line will have their opacity / transparency reset so that the 
                                            // end user can actually see what has happened to their "wire line" connections. 

      let connLineX1 = Number(ConnectionLine.getAttribute("x1")); // The "x1" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the X-Value position that 
                                                                  // the left vertex of the line is positioned at on the 
                                                                  // X-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      let connLineY1 = Number(ConnectionLine.getAttribute("y1")); // The "y1" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the Y-Value position that 
                                                                  // the left vertex of the line is positioned at on the 
                                                                  // Y-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      let connLineX2 = Number(ConnectionLine.getAttribute("x2")); // The "x2" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the X-Value position that 
                                                                  // the right vertex of the line is positioned at on the 
                                                                  // X-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 
                                                                  
      let connLineY2 = Number(ConnectionLine.getAttribute("y2")); // The "y2" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the Y-Value position that 
                                                                  // the right vertex of the line is positioned at on the 
                                                                  // Y-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      newWireLinePathToDraw = 
      `M ${connLineX1} ${connLineY1}
      L ${connLineX2} ${connLineY2}`; // This formula here is a blueprint for a generated pathway that the "wire line" 
                                      // will follow. The "M" means "MOVE", and tells the JavaScript Pen where to start 
                                      // without drawing anything. The "L" means "LINE", and it tells the JavaScript Pen 
                                      // where to draw to when pressing the pen down. 
                                        // !-> This string will be placed into the "d" Path Attribute, which means "DATA", 
                                        //     and this controls how the HTML Path is positioned and transformed. 

      ConnectionLine.setAttribute("d", newWireLinePathToDraw);  // The "d" / DATA attribute for the HTML path "wire line" 
                                                                // is set, and said "wire line" now looks like a "linear 
                                                                // line" between both Logic Gate Objects. 

    }); // The iterative loop that applies the effects of "Line Solver" MODE 0 ends here. 

  } else if (MODE == 1) {   // If this function is called with a "MODE" of 1, then all of the visual wire line connections will 
                            // be styled to be square, orthogonal lines. This means that each "wire line" will look like it's 
                            // going from "Pin" A to "Pin" B, with a "midpoint" line in the middle of the length that either 
                            // goes north or south depending on whether "Pin" B has a higher or lower Y value.  

    solverButtonImageRef.setAttribute("src", "/Media/Layout/lineSolverM1.png"); // Simboard immediately changes the Line
                                                                                // Solver button icon to represent the 
                                                                                // "Orthogonal Styling" mode for the visual Wire 
                                                                                // Line connections. 

    lineRef = document.querySelectorAll('path[tag="interactableObject"]'); // All of the visual "wire line" connections 
                                                                           // that visually represent the wiring of 
                                                                           // Logic Gate objects are stored in this 
                                                                           // variable. Because they are all HTML "Path" 
                                                                           // objects, we fetch all "Paths" with the 
                                                                           // attribute "Tag" that contains the string 
                                                                           // "interactableObject" for validation. 

    lineRef.forEach(ConnectionLine => { // To style each visual "wire line" connection in the Workspace, Simboard must 
                                        // iterate through each of said "wire line" HTML references stored in the "lineRef"
                                        // variable. 

      ConnectionLine.style.opacity = "1.0"; // Each wire line will have their opacity / transparency reset so that the 
                                            // end user can actually see what has happened to their "wire line" connections. 

      let connLineX1 = Number(ConnectionLine.getAttribute("x1")); // The "x1" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the X-Value position that 
                                                                  // the left vertex of the line is positioned at on the 
                                                                  // X-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      let connLineY1 = Number(ConnectionLine.getAttribute("y1")); // The "y1" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the Y-Value position that 
                                                                  // the left vertex of the line is positioned at on the 
                                                                  // Y-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      let connLineX2 = Number(ConnectionLine.getAttribute("x2")); // The "x2" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the X-Value position that 
                                                                  // the right vertex of the line is positioned at on the 
                                                                  // X-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      let connLineY2 = Number(ConnectionLine.getAttribute("y2")); // The "y2" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the Y-Value position that 
                                                                  // the right vertex of the line is positioned at on the 
                                                                  // Y-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 


      midpoint = (connLineX1 + connLineX2) / 2; // The "midpoint" is calculated for the orthogonal line, which dictates 
                                                // where the line will create two 90° angles when going north or south 
                                                // in the Workspace. 

      newWireLinePathToDraw = 
      `M ${connLineX1} ${connLineY1}
      L ${midpoint} ${connLineY1} 
      L ${midpoint} ${connLineY2}
      L ${connLineX2} ${connLineY2}`; // This formula here is a blueprint for a generated pathway that the "wire line" 
                                      // will follow. The "M" means "MOVE", and tells the JavaScript Pen where to start 
                                      // without drawing anything. The "L" means "LINE", and it tells the JavaScript Pen 
                                      // where to draw to when pressing the pen down. 
                                        // !-> This string will be placed into the "d" Path Attribute, which means "DATA", 
                                        //     and this controls how the HTML Path is positioned and transformed. 

      ConnectionLine.setAttribute("d", newWireLinePathToDraw);  // The "d" / DATA attribute for the HTML path "wire line" 
                                                                // is set, and said "wire line" now looks like an "orthogonal 
                                                                // line" between both Logic Gate Objects. 

    }); // The iterative loop that applies the effects of "Line Solver" MODE 1 ends here. 

  } else if (MODE == 2) {   // If this function is called with a "MODE" of 2, then all of the visual wire line connections will 
                            // be styled to be sleek, curvy lines. This means that each "wire line" will look like it's 
                            // going from "Pin" A to "Pin" B, running along a curve over its length that either bends 
                            // north or south depending on whether "Pin" B has a higher or lower Y value.  

    solverButtonImageRef.setAttribute("src", "/Media/Layout/lineSolverM2.png") // Simboard immediately changes the Line
                                                                                // Solver button icon to represent the 
                                                                                // "Curvy Styling" mode for the visual Wire 
                                                                                // Line connections. 

    lineRef = document.querySelectorAll('path[tag="interactableObject"]'); // All of the visual "wire line" connections 
                                                                           // that visually represent the wiring of 
                                                                           // Logic Gate objects are stored in this 
                                                                           // variable. Because they are all HTML "Path" 
                                                                           // objects, we fetch all "Paths" with the 
                                                                           // attribute "Tag" that contains the string 
                                                                           // "interactableObject" for validation. 

    lineRef.forEach(ConnectionLine => { // To style each visual "wire line" connection in the Workspace, Simboard must 
                                        // iterate through each of said "wire line" HTML references stored in the "lineRef"
                                        // variable. 

      ConnectionLine.style.opacity = "1.0"; // Each wire line will have their opacity / transparency reset so that the 
                                            // end user can actually see what has happened to their "wire line" connections. 

      let connLineX1 = Number(ConnectionLine.getAttribute("x1")); // The "x1" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the X-Value position that 
                                                                  // the left vertex of the line is positioned at on the 
                                                                  // X-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      let connLineY1 = Number(ConnectionLine.getAttribute("y1")); // The "y1" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the Y-Value position that 
                                                                  // the left vertex of the line is positioned at on the 
                                                                  // Y-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      let connLineX2 = Number(ConnectionLine.getAttribute("x2")); // The "x2" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the X-Value position that 
                                                                  // the right vertex of the line is positioned at on the 
                                                                  // X-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      let connLineY2 = Number(ConnectionLine.getAttribute("y2")); // The "y2" HTML Path attribute that is attached to each 
                                                                  // "wire line" element contains the Y-Value position that 
                                                                  // the right vertex of the line is positioned at on the 
                                                                  // Y-Axis. 
                                                                  // This is stored in this variable here so that it can 
                                                                  // be used to calculate the paths new "data" pathway 
                                                                  // on its dedicated SVG (Scalar Vector Graphics) 
                                                                  // canvas. 

      offset = (connLineX2 - connLineX1) / 2; // To keep the curve symmetrical, Simboard needs to know how much the 
                                              // curve should "bend" before reaching the destination. This is calculated 
                                              // by finding the horizontal distance between both X-Axis verticies for the 
                                              // "wire line", and dividing it by two. 

      curveUp = connLineX1 + offset; // This variable determines where the curving should start. 

      curveDown = connLineX2 - offset; // This variable determines where the curving should end. 

      newWireLinePathToDraw = 
      `M ${connLineX1} ${connLineY1}
      C ${curveUp} ${connLineY1},
      ${curveDown} ${connLineY2},
      ${connLineX2} ${connLineY2}`; // This formula here is a blueprint for a generated pathway that the "wire line" 
                                    // will follow. The "M" means "MOVE", and tells the JavaScript Pen where to start 
                                    // without drawing anything. The "C" means "CUBIC BÉZIER CURVE", and it tells the 
                                    // JavaScript Pen how to draw a curve with control points when pressing the pen down. 
                                    // Said control points are "curveUp" and "curveDown". 
                                      // !-> This string will be placed into the "d" Path Attribute, which means "DATA", 
                                      //     and this controls how the HTML Path is positioned and transformed. 

      ConnectionLine.setAttribute("d", newWireLinePathToDraw);  // The "d" / DATA attribute for the HTML path "wire line" 
                                                                // is set, and said "wire line" now looks like a "curved 
                                                                // line" between both Logic Gate Objects. 

    });  // The iterative loop that applies the effects of "Line Solver" MODE 2 ends here. 

  } else if (MODE == 3) {   // If this function is called with a "MODE" of 3, then all of the visual wire line connections will 
                            // be styled to have an opacity (how much "light" can pass through this element?) depending on what 
                            // the end user wants. This means that each "wire line" will look like it's more solid or more 
                            // transparent, depending on the float value between 0.0 (fully transparent) and 1.0 (fully solid) that 
                            // the end user states. 

    solverButtonImageRef.setAttribute("src", "/Media/Layout/lineSolverM3.png"); // Simboard immediately changes the Line
                                                                                // Solver button icon to represent the 
                                                                                // "Transparency Styling" mode for the visual Wire 
                                                                                // Line connections. 
                                                                                
    lineRef = document.querySelectorAll('path[tag="interactableObject"]'); // All of the visual "wire line" connections 
                                                                           // that visually represent the wiring of 
                                                                           // Logic Gate objects are stored in this 
                                                                           // variable. Because they are all HTML "Path" 
                                                                           // objects, we fetch all "Paths" with the 
                                                                           // attribute "Tag" that contains the string 
                                                                           // "interactableObject" for validation. 

    newOpacity = prompt("Please enter a number between 0.0 and 1.0 to set the transparency of all lines to, where:\n\n0.0 is fully transparent.\n\n1.0 is not transparent.");
    // The end user is required and expected to enter a float / real value that determines the "opacity" of every single 
    // "wire line".
     
    lineRef.forEach(ConnectionLine => { // To style each visual "wire line" connection in the Workspace, Simboard must 
                                        // iterate through each of said "wire line" HTML references stored in the "lineRef"
                                        // variable. 

      ConnectionLine.style.opacity = parseFloat(newOpacity);  // The actual opacity of each individual "wire line" 
                                                              // is set to be what the end user wanted their 
                                                              // "wire lines" to look like. 

    }); // The iterative loop that applies the effects of "Line Solver" MODE 3 ends here. 

  } else if (MODE == 4) {   // If this function is called with a "MODE" of 4, then all of the visual wire line connections will 
                            // have their positions fixed so that they return to where their pins actually are. This is to solve 
                            // a bug where the wire lines don't actually follow the pins when moving around the Logic Gate 
                            // objects. This way, the end user can using "Mode Fix / Mode Four" (MF) to update how the wire lines 
                            // look on the Workspace. 

    if (parseInt(currentZoomValue) == 1) {  // This Line Solver mode appears to have issues when fixing the positions of the 
                                            // "wire lines" when the Workspace is zoomed in or out. Therefore, the end user must 
                                            // be in the standard Workspace focus / transform in order to "fix" and update their 
                                            // visual Logic Gate object connections. 

      solverButtonImageRef.setAttribute("src", "/Media/Layout/lineSolverM4.png"); // Simboard immediately changes the Line
                                                                                  // Solver button icon to represent the 
                                                                                  // "Fix & Update Positions" mode for the visual 
                                                                                  // Wire Line connections. 

      indexOfLine = 0; // This variable stores the HTML Path "wire line" that will be currently visited. Because the "PairedData"
                       // attribute of the "wire line" corresponds to its specific "jsonSaveWorkspace" index which stores the 
                       // backend information about the Logic Gate object connection (discussed more in the "ioCheck" and 
                       // "initConnect() functions".). Therefore, to "fix" and "update" the positions and "transforms" of the 
                       // visual Logic Gate object connections, this function will need to use the position data in said 
                       // "jsonSaveWorkspace" index. 

      jsonSaveWorkspace.forEach(connecLayer =>{ // To fix the "wire lines", we must first go into each "jsonSaveWorkspace" index, 
                                                // and collect the necessary information for "updating" each "Wire Line" present 
                                                // on the Workspace. 

        lineToFind = document.querySelector(`path[PairedData="${indexOfLine}"`);  // The specific "wire line" that is attached to 
                                                                                  // the currently visited "jsonSaveWorkspace" 
                                                                                  // index is fetched. 

        if (lineToFind != null){  // If the visual "wire line" exists in the HTML DOM, then its correpsonding backend logic data 
                                  // should exist in the "jsonSaveWorkspace" container, therefore, control flow will branch into 
                                  // the instructions below if this statement is true. 

          sourceStartGate = document.getElementById(connecLayer.OBJECTA_INPUTID).children[0]; // Firstly, the HTML reference for 
                                                                                              // the "source" Logic Gate is fetched 
                                                                                              // so that we can access it later on. 

          targetEndGate = document.getElementById(connecLayer.OBJECTB_OUTPUTID).children[0];  // Secondly, the HTML reference for 
                                                                                              // the "target" Logic Gate is fetched 
                                                                                              // so that we can access it later on. 

          console.log("sSGate || teGate == ", sourceStartGate, targetEndGate);  // DEBUGGING INSTRUCTION :: For telling me what 
                                                                                // Simboard thinks is the source node, and what 
                                                                                // it thinks is the target node, so that I can 
                                                                                // see if it has any flaws in its logic or the 
                                                                                // data it is operating with. 

          sourceStartGateFindBox = sourceStartGate.children[0].children[0]; // Then, we find the input "Pin" box for the "source" 
                                                                            // Logic Gate Object. 
                                                                              // The "input" pin is the one on the left, because 
                                                                              // it is taking " inputting " binary signal. 

          targetEndGateFindBox = targetEndGate.children[2].children[0]; // Afterwards, we find the output "Pin" box for the 
                                                                        // "target" Logic Gate Object. 
                                                                              // The "output" pin is the one on the right, because 
                                                                              // it is " outputting " binary signal. 
          console.log("sSGateFB || teGateFB == ", sourceStartGateFindBox, targetEndGateFindBox);  // DEBUGGING INSTRUCTION :: For 
                                                                                                  // telling me that Simboard 
                                                                                                  // knows where and what "pins" 
                                                                                                  // it should operate on relative 
                                                                                                  // to the source and target nodes 
                                                                                                  // identifed earlier. 

          sourceBoxPosition = sourceStartGateFindBox.getBoundingClientRect(); // This instruction returns the size and position 
                                                                              // of the source Logic Gate Objects' input "Pin" 
                                                                              // relative to the Browser Resolution (Viewport). 

          targetBoxPosition = targetEndGateFindBox.getBoundingClientRect(); // This instruction returns the size and position 
                                                                            // of the source Logic Gate Objects' input "Pin" 
                                                                            // relative to the Browser Resolution (Viewport). 

          viewportReference = document.getElementById("Workspace").getBoundingClientRect(); // The reference of the Workspace 
                                                                                            // is fetched from the HTML DOM, and 
                                                                                            // its size and position is taken 
                                                                                            // relative to the Browser Resolution 
                                                                                            // (Viewport). 

          newDrawPointX1 = (sourceBoxPosition.left + sourceBoxPosition.width / 2) - viewportReference.left;
          // In order to get the X-Axis position of the source Logic Gate objects' "Pin", we need to get its 
          // horizontal "center" point, which is done by adding the "left" position value to the width of 
          // said Logic Gate "Pin" and dividing by 2, then subtracting the Workspace "left" position value 
          // so that the returned new X-Axis position is relative to the Workspace, and not to the whole 
          // Simboard application (aka. the "Base" in the Simboard HTML DOM).  

          newDrawPointY1 = (sourceBoxPosition.top + sourceBoxPosition.height / 2) - viewportReference.top;
          // In order to get the Y-Axis position of the source Logic Gate objects' "Pin", we need to get its 
          // vertical "center" point, which is done by adding the "top" position value to the height of 
          // said Logic Gate "Pin" and dividing by 2, then subtracting the Workspace "top" position value 
          // so that the returned new Y-Axis position is relative to the Workspace, and not to the whole 
          // Simboard application (aka. the "Base" in the Simboard HTML DOM).  

          newDrawPointX2 = (targetBoxPosition.left + targetBoxPosition.width / 2) - viewportReference.left;
          // In order to get the X-Axis position of the target Logic Gate objects' "Pin", we need to get its 
          // horizontal "center" point, which is done by adding the "left" position value to the width of 
          // said Logic Gate "Pin" and dividing by 2, then subtracting the Workspace "left" position value 
          // so that the returned new X-Axis position is relative to the Workspace, and not to the whole 
          // Simboard application (aka. the "Base" in the Simboard HTML DOM).  

          newDrawPointY2 = (targetBoxPosition.top + targetBoxPosition.height / 2) - viewportReference.top;
          // In order to get the Y-Axis position of the target Logic Gate objects' "Pin", we need to get its 
          // vertical "center" point, which is done by adding the "top" position value to the height of 
          // said Logic Gate "Pin" and dividing by 2, then subtracting the Workspace "top" position value 
          // so that the returned new Y-Axis position is relative to the Workspace, and not to the whole 
          // Simboard application (aka. the "Base" in the Simboard HTML DOM).  

          lineToFind.setAttribute("x1", newDrawPointX1);  // The X-Value information holder has its value 
                                                          // updated to represent the lines new left vertex 
                                                          // position. 

          lineToFind.setAttribute("y1", newDrawPointY1);  // The Y-Value information holder has its value 
                                                          // updated to represent the lines new left vertex 
                                                          // position. 

          lineToFind.setAttribute("x2", newDrawPointX2);  // The X-Value information holder has its value 
                                                          // updated to represent the lines new right vertex 
                                                          // position. 

          lineToFind.setAttribute("y2", newDrawPointY2);  // The Y-Value information holder has its value 
                                                          // updated to represent the lines new right vertex 
                                                          // position. 

          figuredPath = 
          `M ${newDrawPointX1} ${newDrawPointY1}
          L ${newDrawPointX2} ${newDrawPointY2}`; // The new data pathway that the currently visited "wire line" 
                                                  // will follow is generated via this formula here, where the 
                                                  // JavaScript Pen is told to "M" (for MOVE) to the correct 
                                                  // position on the X and Y axis, and then "L" (to draw) to the 
                                                  // correct position on the X and Y axis. 

          lineToFind.setAttribute("d", figuredPath);  // The "d" / DATA attribute for the HTML path "wire line" 
                                                      // is set, and said "wire line" now looks like a "curved 
                                                      // line" between both Logic Gate Objects. 

        };  // The validator to check whether the "wire line" actually exists or not ends here. 

        indexOfLine++;  // The "PairedData" to find variable is incremented so that the next "jsonSaveWorkspace" 
                        // connection can be visited, instead of being stuck visiting the same index forever. 

        console.log("indexOfLine == ", indexOfLine);  // DEBUGGING INSTRUCTION :: For confirming to me that the line solver 
                                                      // is in fact iterating through each line found in the HTML DOM 
                                                      // structure.

      }); // The iterative loop that applies some of the effects of "Line Solver" MODE 4 ends here. 

      indexOfLine = 0;  // After the iterative loop, the variable for fetching each "wire line" based on the "jsonSaveWorkspace" 
                        // index is reset, so that the same process can occur again if called / recalled. 

      lineRef = document.querySelectorAll('path[tag="interactableObject"]');  // All of the visual "wire line" connections 
                                                                              // that visually represent the wiring of 
                                                                              // Logic Gate objects are stored in this 
                                                                              // variable. Because they are all HTML "Path" 
                                                                              // objects, we fetch all "Paths" with the 
                                                                              // attribute "Tag" that contains the string 
                                                                              // "interactableObject" for validation. 

      lineRef.forEach(ConnectionLine => {   // To style each visual "wire line" connection in the Workspace, Simboard must 
                                            // iterate through each of said "wire line" HTML references stored in the "lineRef"
                                            // variable. 

        ConnectionLine.setAttribute("stroke", "#000000"); // Just to display what has actually occured for the end user, the 
                                                            // colour of all "fixed and updated lines" is changed to be pure black 
                                                            // in Hexadecimal (HEX). 

        ConnectionLine.setAttribute("stroke-width", "7.5"); // To ensure that the end user can see what has occured, the thickness / 
                                                            // width of the "wire lines" is reset to its default styling value. 

        ConnectionLine.style.opacity = 1.0; // Each wire line will have their opacity / transparency reset so that the 
                                            // end user can actually see what has happened to their "wire line" connections. 

      }); // The iterative loop that applies the rest of the effects of "Line Solver" MODE 4 ends here. 

    } else {  // If the end user is not viewing the Workspace in its default zoom setting, then control flow will go into the 
              // instructions seen below in this branch. 

      alert("Line Solver Type 4 cannot accurately solve the transforms of each line when you are zoomed in / out.\n\nPlease zoom back in to the default scale to activate this Line Solver!\n\nVisit the 'Workspace Data' panel in the Object Menu to see your current zoom scale.");
      // The end user is notified that they must return to the default zoom setting, either by using the "RWT" command in the 
      // "Talk To System" function, or by manually zooming in or zooming out to accomodate for this. 

      console.warn("Line Solver Type 4 cannot accurately solve the transforms of each line when you are zoomed in / out.\n\nPlease zoom back in to the default scale to activate this Line Solver!\n\nVisit the 'Workspace Data' panel in the Object Menu to see your current zoom scale.");
      // DEBUGGING INSTRUCTION :: If I am in the developer tools console log, I must be able to see that the system is sending 
      // control flow into this decision branch, which is why this instruction is crucial for the development of this function. 

    };  // The control flow branching for if the end user is in the default zoom or not to prevent visual wiring errors ends 
        // here. 

  } else if (MODE == 5) {   // If this function is called with a "MODE" of 5, then all of the visual wire line connections will 
                            // be styled to have a colour depending on what the end user wants. The end user can decide to make 
                            // all of the wire lines black, all of the wire lines a colour of their choice, or to randomly 
                            // colour every wire line connection at once. 

    solverButtonImageRef.setAttribute("src", "/Media/Layout/lineSolverM5.png"); // Simboard immediately changes the Line
                                                                                // Solver button icon to represent the 
                                                                                // "Colour Styling" mode for the visual Wire 
                                                                                // Line connections. 

    lineRef = document.querySelectorAll('path[tag="interactableObject"]'); // All of the visual "wire line" connections 
                                                                           // that visually represent the wiring of 
                                                                           // Logic Gate objects are stored in this 
                                                                           // variable. Because they are all HTML "Path" 
                                                                           // objects, we fetch all "Paths" with the 
                                                                           // attribute "Tag" that contains the string 
                                                                           // "interactableObject" for validation. 

    setColourMode = prompt("Please enter an integer number based on how you want to colour every wire, where: \n\n0 - Colour all wires Black\n1 - Colour all wires to a HEX colour of your choice\n2 - Randomly colour every wire");
    // The end user is required and expected to enter an integer mode value that determines how every single "wire line"
    // will be coloured.

    if (setColourMode == 0) { // If the end user has entered the integer value "0" in the prompt above, then the wire lines 
                              // should all be coloured pure, solid "black", therefore, control flow should flow into this 
                              // branch here. 

      lineRef.forEach(ConnectionLine => {   // To style each visual "wire line" connection in the Workspace, Simboard must 
                                            // iterate through each of said "wire line" HTML references stored in the "lineRef"
                                            // variable. 

        ConnectionLine.setAttribute("stroke", "#000000");   // Each "wire line" is individually coloured pure "black" in 
                                                              // Hexadeciaml (HEX). 

      }); // The iterative loop that applies the effects of "Line Solver" MODE 5, SUB-MODE 0 ends here. 

    } else if (setColourMode == 1) {  // If the end user has entered the integer value "1" in the prompt above, then the wire lines 
                                      // should all be coloured to a specific Hexademcial (HEX) value that the end user wants or 
                                      // prefers, therefore, control flow should flow into this branch here. 

      newSetColour = prompt("Please enter a HEX colour to set all wires to: ");
      // The end user is required and expected to enter a Hexadecimal (HEX) value that determines the colour of every single 
      // "wire line".

      if (newSetColour[0] == "#") { // This local guard / flag here provides a form of HEX-Value check validation, seen in 
                                    // similar manners to the "customisation" function in SCRIPT 001. As long as the end user 
                                    // enters a string with a hastag / pound sign / # at the start, then Simboard will treat 
                                    // it as a Hexadecimal (HEX) value for styling every "wire line" in the Workspace.  

        lineRef.forEach(ConnectionLine => { // To style each visual "wire line" connection in the Workspace, Simboard must 
                                            // iterate through each of said "wire line" HTML references stored in the "lineRef"
                                            // variable. 

          ConnectionLine.setAttribute("stroke", newSetColour);  // Each "wire line" is individually coloured to the Hexadecimal 
                                                                // (HEX) value that was specified in the prompt above. 

        }); // The iterative loop that applies the effects of "Line Solver" MODE 5, SUB-MODE 1 ends here. 

      };  // The checker for if the entered colour to set each "wire line" is a Hexadecimal (HEX) value ends here. 

    } else if (setColourMode == 2) {  // If the end user has entered the integer value "2" in the prompt above, then the wire lines 
                                      // should all be coloured completely randomly, therefore, control flow should flow into this 
                                      // branch here. 

      lineRef.forEach(ConnectionLine => {  // To style each visual "wire line" connection in the Workspace, Simboard must 
                                           // iterate through each of said "wire line" HTML references stored in the "lineRef"
                                           // variable. 

        newRandomColour = generateRandHex();  // This function, "generateRandHex()", is called upon each iteration, and its 
                                              // returned value (e.g. #0C44E5) is stored in this variable "newRandomColour". 

        ConnectionLine.setAttribute("stroke", newRandomColour);   // The newly generated random Hexadecimal (HEX) colour is 
                                                                  // set to be the currently visited "wire line"'s visual 
                                                                  // colour in this iteration. 

      }); // The iterative loop that applies the effects of "Line Solver" MODE 5, SUB-MODE 2 ends here. 

    };  // The control flow branch for what occurs when the end user activates a specific "sub-mode" of the "colouring" styler 
        // for the Line Solver ends here. 

  } else if (MODE == 6){   // If this function is called with a "MODE" of 6, then all of the visual wire line connections will 
                           // be styled to have a thickness / width depending on what the end user wants. This means that the 
                           // end user can style every wire line connection in the Workspace to be really thin, really thick 
                           // or the default that it has always been! 

    solverButtonImageRef.setAttribute("src", "/Media/Layout/lineSolverM6.png"); // Simboard immediately changes the Line
                                                                                // Solver button icon to represent the 
                                                                                // "Width Styling" mode for the visual Wire 
                                                                                // Line connections. 

    lineRef = document.querySelectorAll('path[tag="interactableObject"]'); // All of the visual "wire line" connections 
                                                                           // that visually represent the wiring of 
                                                                           // Logic Gate objects are stored in this 
                                                                           // variable. Because they are all HTML "Path" 
                                                                           // objects, we fetch all "Paths" with the 
                                                                           // attribute "Tag" that contains the string 
                                                                           // "interactableObject" for validation. 

    newThicknessToUpdate = prompt("Please enter a float value to determine the thickness for all wires to copy!\n\nA value of 7.5 is the default.");
    // The end user is required and expected to enter a float / real value that determines the "thickness" of every single 
    // "wire line".

    lineRef.forEach(ConnectionLine => { // To style each visual "wire line" connection in the Workspace, Simboard must 
                                        // iterate through each of said "wire line" HTML references stored in the "lineRef"
                                        // variable. 

      ConnectionLine.setAttribute("stroke-width", newThicknessToUpdate);  // The actual width of each individual "wire line" 
                                                                          // is set to be what the end user wanted their 
                                                                          // "wire lines" to look like, in pixels. 

    }); // The iterative loop that applies the effects of "Line Solver" MODE 6 ends here. 

  } else {  // If this function is called with a mode that does not exist / is out of the range provided, then control flow 
            // will immediately flow into this branch here. 

    console.warn("\nCould not find the specific Line Solver method entered!\n");  // A simple alert is given to the end user, 
                                                                                  // or developer, to notify them that they 
                                                                                  // may be trying to use a wrong "Line Solver" 
                                                                                  // mode. 

  };  // The branching for if the end user is trying to utilise a valid "Line Solver" mode ends here. 

};  // The "Line Solver" function that styles, colours or fixes each "Wire Line" visual connection in the Workspace ends 
    // here. 



// *** SCRIPT 034 *** -- Ends here 
