//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 041 *** -- Starts here 
// The purpose of the below code is to actually simulate the Logic Gate circuit. Once the end user toggles 
// the inputs of the Logic Gate circuit (in SCRIPT 039), this function is called. This function, 
// discernBoolean() takes no parameters, and solely operates on the jsonSaveWorkspace connection 
// container. This container is iterated through, and the pairs of objects are checked for their state 
// and type. The flow of Boolean signal is then manipulated across the circuit, and this function 
// sets the thumbnail of each object to represent their ON or OFF state accordingly to visually 
// represent this. To take into account all Logic Gate objects and their state, this function runs 
// recursively from the inputs (Hold Buttons) and goes to the Nth object that is connected from said 
// input, where N is determined by the "calculationDepth" variable. This is what is meant by the 
// "Engine Power", and so larger circuit projects will have a longer connection of objects from a Hold 
// Button, e.g. 17 objects from start. Therefore, the calculation depth / engine power will need to be 
// 17 to account for the recursive nature of this program. 
  // BE WARNED! Setting the Engine Power too high causes incredible lag and resource handling inefficieny, 
  // so be careful when operating with very large circuits with many "steps" from inputs. (5000 seems like 
  // a standard "breaking point" for the Simboards' "Engine Power").



function discernBoolean() { // The function "discernBoolean()" is called which contains controls the 
                            // "Simulation Logic" behind the Simboard application. No parameters are 
                            // needed, yet it is controlled by the "calculationDepth" variable talked 
                            // about earlier. 

  updatedJsonView = jsonSaveWorkspace.filter(con => con !== null);  // All of the "null" values are 
                                                                    // filtered out of the Workspace 
                                                                    // so that no "accessed none" errors 
                                                                    // appear later on when operating 
                                                                    // on the connection data. 

  updatedJsonView.forEach(connLayr => { // The new, and updated (filtered) view of the Workspace is  
                                        // iterated through with this loop here. 

    connA = connLayr.CONNECTEDOBJECT_A;

    connB = connLayr.CONNECTEDOBJECT_B; 

    connAParentType = connA.parentNode.getAttribute("gatetype");  // The Gate Type of the source node is 
                                                                  // fetched from the HTML DOM Logic Gate 
                                                                  // Object element. 

    connBParentType = connB.parentNode.getAttribute("gatetype");  // The Gate Type of the target node is 
                                                                  // fetched from the HTML DOM Logic Gate 
                                                                  // Object element. 

    connAParentIsOn = connA.parentNode.getAttribute("state");   // The state of the source node is 
                                                                // fetched from the HTML DOM Logic Gate 
                                                                // Object element. 

    connBParentIsOn = connB.parentNode.getAttribute("state");   // The state of the target node is 
                                                                // fetched from the HTML DOM Logic Gate 
                                                                // Object element. 

    if (connAParentIsOn == 1 || connBParentIsOn == 1) { // The logic to determine whether the "speaker song" 
                                                        // should play is operated here.  

      if (connAParentType == "Speaker" || connBParentType == "Speaker") {

        enabledSound = true; 

      } else {

        enabledSound = false; 

      };

    } else if (connAParentIsOn == 0 && connBParentIsOn == 0){ 

      enabledSound = false; 

    } else {

      console.warn("An error occured with the sound handler!"); // DEBUGGING INSTRUCTION :: This will 
                                                                // notify me if the logic behind the 
                                                                // music handling mechanic is faulty 
                                                                // or not. 

    };

  });

  musicHandler(choiceOfSongByUser); // Because of these checks, the system lags a little bit. 

  const inputTracker = {}; // All of the Logic Gate Objects have their state pushed to this object 
                           // here so that recursive operations can be conducted based on this information 
                           // later on. 

  jsonSaveWorkspace.forEach(conn => {

    if (!conn) return;

    const sourceNode = conn.CONNECTEDOBJECT_A.parentNode;

    const targetNode = conn.CONNECTEDOBJECT_B.parentNode; 

    const targetID = targetNode.id;

    console.log("PN SouNod == ", sourceNode);  // DEBUGGING INSTRUCTION :: For checking the source node variable is 
                                               // correct, and if it isn't, then the function will fail as it may 
                                               // be operating in a backwards, or multi-direction manner.

    console.log("PN TarNod == ", targetNode);  // DEBUGGING INSTRUCTION :: For checking the target node variable is 
                                               // correct, and if it isn't, then the function will fail as it may 
                                               // be operating in a backwards, or multi-direction manner.
    
    console.log("TARGET IDENTIFICATION == ", targetID); // DEBUGGING INSTRUCTION :: For confirming that the unique 
                                                        // ID of the object to visit is one that exists and one 
                                                        // that can be accessed by the connections given in the 
                                                        // jsonSaveWorkspace container. 

    if (!inputTracker[targetID]) {  

      inputTracker[targetID] = [];  // The array of incoming binary signal is applied to the Logic Gate object if it 
                                    // does not exist yet. 

    };

    const sourceState = parseInt(sourceNode.getAttribute("state"));

    inputTracker[targetID].push(sourceState); // The incoming binary signal is pushed from the transmitter to the 
                                              // receiver Logic Gate object. 

  });

  for (const gateId in inputTracker) {  // This loop here goes through every Logic Gate Object that contains a binary 
                                        // signal, and calculates its output from its own operation. 

    const gateNode = document.getElementById(gateId);

    const type = gateNode.getAttribute("gatetype");

    const inputs = inputTracker[gateId]; 

    let finalState = 0;

    if (type === "Lightbulb" || type === "OR") {

      console.log("EITHER LIGHTBULB, SPEAKER OR THE OR GATE VISITED!"); // DEBUGGING INSTRUCTION :: For confirmation that 
                                                                        // a 1 -> 1 object has been toggled.

      finalState = inputs.includes(1) ? 1 : 0;

      console.log("EITHER LIGHTBULB, SPEAKER OR THE OR GATE IS RETURNING == ", finalState)  // DEBUGGING INSTRUCTION :: For 
                                                                                            // confirmation that the Logic 
                                                                                            // Gate object has been toggled 
                                                                                            // in the Backend correctly. 

    } else if (type == "Speaker") {

      console.log("SPEAKER HAS BEEN VISITED"); // DEBUGGING INSTRUCTION :: For confirmation that 
                                               // a 1 -> 1 special object has been toggled.

      finalState = inputs.includes(1) ? 1 : 0;

      console.log("SPEAKER IS RETURNING == ", finalState)  // DEBUGGING INSTRUCTION :: For 
                                                           // confirmation that the Logic 
                                                           // Gate object has been toggled 
                                                           // in the Backend correctly. 

    } else if (type === "AND") {

      console.log("AND GATE VISITED!"); // DEBUGGING INSTRUCTION :: For confirmation that 
                                        // a 1 && 1 -> 1 object has been toggled.

      const hasEnoughInputs = inputs.length >= 2;

      const allInputsActive = inputs.every(val => val === "1" || val === 1);

      finalState = (hasEnoughInputs && allInputsActive) ? 1 : 0;

      console.log("AND GATE IS RETURNING == ", finalState) // DEBUGGING INSTRUCTION :: For 
                                                           // confirmation that the Logic 
                                                           // Gate object has been toggled 
                                                           // in the Backend correctly. 

    } else if (type === "XOR") {

      console.log("AND GATE VISITED!"); // DEBUGGING INSTRUCTION :: For confirmation that 
                                        // a 1 ^ 1 -> 1 object has been toggled.

      const activeCount = inputs.filter(v => Number(v) === 1).length;

      finalState = (activeCount % 2 !== 0) ? 1 : 0;

      console.log("AND GATE IS RETURNING == ", finalState) // DEBUGGING INSTRUCTION :: For 
                                                           // confirmation that the Logic 
                                                           // Gate object has been toggled 
                                                           // in the Backend correctly. 

    } else if (type === "NOT") {

      console.log("NOT GATE VISITED!") // DEBUGGING INSTRUCTION :: For confirmation that 
                                       // a ¬1 -> 1 object has been toggled.

      const signal = inputs.includes(1) || inputs.includes("1") ? 1 : 0;

      if (notStateDefault == 1) {

        finalState = (signal === 0) ? 1 : 0; // FLIPS DA RESULT 

      } else {

        finalState = (signal === 1) ? 1 : 0;

      };

      console.log("MULTI INPUT NOT GATE IS RETURNING == ", finalState); // DEBUGGING INSTRUCTION :: For 
                                                                        // confirmation that the Logic 
                                                                        // Gate object has been toggled 
                                                                        // in the Backend correctly. 

    } else {

      console.log("CRITICAL MAJOR ERROR !!! LOGIC GATE BOOLEAN NOT CALCULATED") // DEBUGGING INSTRUCTION :: For 
                                                                                // notifying me that something has 
                                                                                // gone wrong with the Boolean 
                                                                                // recursive math. 

    };

    gateNode.setAttribute("state", finalState);

    // BELOW :: Is the logic that controls the visual thumbnail of the Logic Gate Object depending on its 
    // state. If it contains a state of "1", then it will be visually "activated", vice versa. 

    const folder = finalState === 1 ? "ActivatedState" : "DeactivatedState";

    const suffix = finalState === 1 ? "_Activated.png" : "_Deactivated.png";

    const specSpeakerSuffix = finalState === 1 ? "_Activated.gif" : "_Deactivated.png"

    if (type != "Speaker") {

      if(gateNode.children[0].children[1]) {

        gateNode.children[0].children[1].setAttribute("src", `/Media/${folder}/${type}${suffix}`);
          
      };

    } else {

      if(gateNode.children[0].children[1]) {

        gateNode.children[0].children[1].setAttribute("src", `/Media/${folder}/${type}${specSpeakerSuffix}`);

      };

    };

  };

  // BELOW :: Similar logic used earlier is used to iterate through the "wire lines" so that they are "pulsating" 
  // or not depending on their state. 

  fetchIndex = 0; 

  jsonSaveWorkspace.forEach(cnnLyr => {

    if (cnnLyr != null) {

      sourceObj = cnnLyr.CONNECTEDOBJECT_A.parentNode; 

      targetObj = cnnLyr.CONNECTEDOBJECT_B.parentNode; 

      sourceState = sourceObj.getAttribute("state");

      targetState = targetObj.getAttribute("state");

      lineToPulse = document.querySelector(`path[PairedData="${fetchIndex}"`);

      if (sourceState == 1 && targetState == 1) {

        wireLinePulsate(lineToPulse, true);
  
      } else if (sourceState == 1 && targetState == 0) {
      
        wireLinePulsate(lineToPulse, true);

      } else {

        wireLinePulsate(lineToPulse, false);

      };

      fetchIndex++; 

    } else {

      fetchIndex++; 

    };

  }); 

};  // The function for simulating the Workspace Circuit Project ends here. 



