//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 042 *** -- Starts here 
// The purpose of the below code is to ensure that the end user cannot zoom in and out via convential 
// means with their controller. This function prevents zooming the Webpage in and out via the CTRL && 
// Scrollwheel only. This is to protect the standard "look" of Simboard and so that the visual styling 
// and structural elements of the program do not break. This can be bypassed by the Browsers' zoom in 
// function by navigating to the three dots in the corner, yet this acts as a way to stop accidental 
// zooming and to direct the end user to use Simboards own zoom function for the Workspace, by using 
// K and L to zoom in and out respectively.



window.addEventListener('wheel', function(e) {  // This function takes the scroll wheel itself as a parameter, and 
                                                // attaches an event listener to it so that when the end user tries 
                                                // to zoom in or out using it, Simboard will deny said action. 

  if (e.ctrlKey) {  // If the end user is clicking or pressing the "Control" key on their keyboard, control flow 
                    // runs into here.

    e.preventDefault(); // The default "outcome" that would occur when the end user clicks or presses the "Control" 
                        // key while scrolling is denied by the system, and is returned. 

    if (e.deltaY < 0) { // If the scroll wheel is detected to be moving, this event listener is activated, and 
                        // if it has a "delta" direction of over 0, the end user is trying to "zoom in", therefore, 
                        // if the end user is trying to zoom in via using the input combination of "CTRL + SCROLL 
                        // UP", control flow goes into this branch. 

      console.log("System lock prevented the browser zooming in via the mouse to preserve the UI Layout.");
      // DEBUGGING INSTRUCTION ABOVE :: For telling me that the system should prevent me from zooming in via the 
      // scroll wheel.

    } else { // If the scroll wheel is detected to be moving, this event listener is activated, and 
              // if it has a "delta" direction of below 0, the end user is trying to "zoom out", therefore, 
              // if the end user is trying to zoom out via using the input combination of "CTRL + SCROLL 
              // DOWN", control flow goes into this branch. 

      console.log("System lock prevented the browser zooming out via the mouse the preserve the UI Layout.");
      // DEBUGGING INSTRUCTION ABOVE :: For telling me that the system should prevent me from zooming out via the 
      // scroll wheel.

    };  // The conditional branch switch for what occurs when the end user is trying to zoom IN or OUT of the 
        // Simboard application ends here. 

  };  // The validator which allows control flow in if the end user is pressing the "CTRL" / Control key down ends 
      // here. 

}, {passive: false}); // To prevent the browser from overwriting what this function sets out to do, we set it to not 
                      // be passive, but instead hostile, so that the end user cannot zoom in or out via the scroll 
                      // wheel and control key ever.  
                      // With this final instruction, this event listener ends its operation here. 



// *** SCRIPT 042 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 043 *** -- Starts here 
// The purpose of the below code is to ensure that the end user cannot zoom in and out via convential 
// means with their controller. This function prevents zooming the Webpage in and out via CTRL && NumPAD + 
// or CTRL && NumPAD -. This is to protect the standard "look" of Simboard and so that the visual styling 
// and structural elements of the program do not break. This can be bypassed by the Browsers' zoom in 
// function by navigating to the three dots in the corner, yet this acts as a way to stop accidental 
// zooming and to direct the end user to use Simboards own zoom function for the Workspace, by using K 
// and L to zoom in and out respectively.



window.addEventListener('keydown', function(e) {  // This function takes the keyboard itself as a parameter, and 
                                                  // attaches an event listener to it so that when the end user tries 
                                                  // to zoom in or out using it, Simboard will deny said action. 

    if (e.ctrlKey && (e.key === '=' || e.key === '-' || e.key === '+')) { // If the end user is clicking or pressing 
                                                                          // the Control Key, and either the "=", the 
                                                                          // "-" or the "+" key at the same time, then 
                                                                          // control flow will pass through this 
                                                                          // validator here. 

        e.preventDefault(); // The default "outcome" that this input combination provides is disabled, which means 
                            // the end user cannot zoom IN or OUT of the Simboard web application via this method. 

        console.log("System lock prevented the browser zooming in or out via the keyboard Workspace layout.");
        // DEBUGGING INSTRUCTION ABOVE :: For telling me that the system should prevent me from zooming in and out 
        // via the NumPAD.

    };  // The validator which allows control flow in if the end user is pressing the "CTRL" / Control key and any 
        // other zoom-related key down ends here. 

});  // The event listener for preventing the method of zooming IN or OUT via the keyboard ends here. 



// *** SCRIPT 043 *** -- Ends here 
