//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 045 *** -- Starts here 
// The purpose of the below code is to give the end user the ability to "Talk to the System" / "Talk To 
// Simboard directly". This can be done in the form of entering abbreviated commands into a prompt, 
// which tell Simboard to perform a specific action that is not related to the main purpose of Simboard, 
// just like a Command Prompt! This function allows the end user to configure or control Simboard more 
// than the other functions in the File Menu ever could, and instead of adding endless buttons, 
// every non-essential function is grouped into this one, and can be performed inside of this function. 
// Commands range from UI Specific, to Logic Gate simulation oriented, all the way to Screenshotting the 
// circuit, which greatly improves UX (User Experience) for users trying to get into more technical 
// understanding of Simboard. Yet, they need to know the commands to use, which can be a nuisance. 



talkToSysButtonReference = document.getElementById("talkToSystem"); // A reference to the "Talk To System" 
                                                                    // Button in the HTML DOM is stored in this 
                                                                    // variable here. 

insertedCmd = null;   // This variable will contain the command that the end user will input into the "command 
                      // prompt", for future instructions to make decisions from. 

talkToSysButtonReference.onclick= function(){ // An "on click" event listener is attached to the "Talk To System" 
                                              // button fetched earlier, so that when the end user does click on 
                                              // said button, the "talkToSystem()" function will fire immediately. 

  talkToSystem(); // The "talkToSystem()" function is called with no parameters so that when it does activate, it   
                  // will ask the end user for a Simboard "command" to use. 

};  // The event listener that controls what occurs when the end user clicks on the "Talk To System" button ends 
    // here. 

function talkToSystem(cmd) {  // The "talkToSystem()" function is called, and with it, a parameter that will hold 
                              // the instruction that the end user wants to execute. 

  if (cmd != null){   // If the command that the end user wants to execute is not "null", then it is stored inside 
                      // of the "insertedCommand" variable to be used later on. 

    insertedCmd = cmd; // This variable holds the command to be executed from the end user / developer. 

  } else {  // If the command that the end user wants to execute is "null", then a prompt is shown asking the end user 
            // what they want to execute. If the end user inputs a command, it is stored inside of the "insertedCommand" 
            // variable to be used later on. 

    insertedCmd = prompt("QUICK INPUT: Please enter a command to talk to Simboard and control it\n\nEnter the command 'MENU' to see the list of commands to use: ");
    // A JavaScript prompt is displayed to the end user which is then stored inside of the "insertedCommand" variable if 
    // the end user inputs data into it. 

  };  // The conditional branch which determines what the command to execute will be depending on how this function is 
      // called ends here. 

  switch (insertedCmd.toUpperCase()){ // A switch statement is defined to produce an outcome depending on the parsed parameter. 

    case "MENU":  // If the inputted command is "MENU", then another prompt will appear displaying a set amount of very useful 
                  // Simboard commands. 
      
      newCmd = prompt("The comprehensive list of commands:\n\n\n-- Special Commands --\nSSV - Set Specific Value (for Developers)\nHFR - Force Refresh Simboard\nARG - Allow Refresh Guard\nSRG - Stop Refresh Guard\nADG - Allow Debug Guard\nSDG - Stop Debug Guard\nDDV - Display Debug Values (for Developers)\n\n-- Regular Commands --\nMENU - View all commands\nHGAA - Hide Grid & Axis\nHAO - Hide Axis Only\nHGO - Hide Grid Only\nSGAA - Show Grid & Axis\nSGO - Show Grid Only\nSAO - Show Axis Only\n\nInput 'MORE' to see more commands!");

      if (newCmd.toUpperCase() == "MORE") {

        talkToSystem("MORE");

      } else {

        talkToSystem(newCmd);

      };

      break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
              // both outcomes. 

    case "MORE":  // If the inputted command is "MORE", then another prompt will appear displaying another set of very useful 
                  // Simboard commands. 

      newCmd = prompt("RSV - Reset Specific Value (for Developers)\nSSC - Screenshot Circuit\nSSS - Screenshot entire Simboard App\nRBC - Reset Box Click\nCSS - Change Speaker Song\nRWT - Reset Workspace Transform\nVWT - View Workspace Transform\nSWT - Set Workspace Transform\nTAN - Toggle All NOT Logic Gates\nCW - Clear Workspace\nTPULSE - Toggle Pulse Type\nCPULSE - Toggle Pulse Colour\nSPULSE - Toggle Pulse Speed\nWPULSE - Toggle Pulse Width\nTT - Change Toggle Aid Transparency");

      talkToSystem(newCmd);

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "HFR":  // If the inputted command is "HFR" (Hard Force Reset), then the Simboard application will refresh 
                 // automatically, wiping all of the Simboard session data clean. 

      guard = confirm("This will wipe your current session from RAM which will clear all layout and circuit data.\n\nClick CANCEL to halt this command.\nClick OK to proceed.");

      if (guard == true) {

        window.location.href = window.location.pathname + "?" + Date.now();

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SFR":  // If the inputted command is "SFR" (Soft Force Reset), then the Simboard application will reset all of 
                 // the Global Variables in the backend automatically, with the attempt of negating current bugs being 
                 // experienced in the session. 

      guard = confirm("This may break the functionality of Simboard, are you sure you want to proceed with this command?\n\nClick CANCEL to halt this command.\nClick OK to proceed.");

      if (guard == true) {

        resetGlobalsToDefault(null, null); // resets everything 

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "HAO":  // If the inputted command is "HAO" (Hide Axis Only), then the Simboard application will hide the visual Axies 
                 // on the Workspace. 

      drawAxis(1, null, null)

      drawGrid(0, tempStylesContainer.tempGridLineColour)

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "HGO":  // If the inputted command is "HGO" (Hide Grid Only), then the Simboard application will hide the visual Grid 
                 // on the Workspace. 

      drawGrid(1, null)

      drawAxis(0, tempStylesContainer.tempAxisYColour, tempStylesContainer.tempAxisXColour)

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "HGAA":  // If the inputted command is "HGAA" (Hide Grid And Axis), then the Simboard application will hide both the 
                  // Grid and Axies on the Workspace. 

      drawAxis(1, null, null)

      drawGrid(1, null)

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SGAA":  // If the inputted command is "SGAA" (Show Grid And Axis), then the Simboard application will show both the 
                  // Grid and Axies on the Workspace. 

      drawGrid(0, tempStylesContainer.tempGridLineColour);

      drawAxis(0, tempStylesContainer.tempAxisYColour, tempStylesContainer.tempAxisXColour);

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SAO":  // If the inputted command is "SAO" (Show Axis Only), then the Simboard application will show the Axis only 
                 // on the Workspace. 

      drawGrid(1, null);

      drawAxis(0, tempStylesContainer.tempAxisYColour, tempStylesContainer.tempAxisXColour);

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SGO":  // If the inputted command is "SGO" (Show Grid Only), then the Simboard application will show the Grid only 
                 // on the Workspace. 

      drawAxis(1, null, null); // do ui wipes before to stop clearRect from deleting the current UI

      drawGrid(0, tempStylesContainer.tempGridLineColour);

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "RSV":  // If the inputted command is "RSV" (Reset Specific Value), then the Simboard application will reset a specific 
                 // Global Variable specified by the end user / developer. 

      newCmd = prompt("Please enter the variable, container or function (keeping Case-Sensitivity in mind) you'd like to reset its to default value: ");

      guard = confirm("This may break the functionality of Simboard, are you sure you want to proceed with this command?\n\nClick CANCEL to halt this command.\nClick OK to proceed.");

      if (guard == true) {

        resetGlobalsToDefault(`${newCmd}`, null); // resets a specific value 

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "ARG":   // If the inputted command is "ARG" (Allow Refresh Guard), then the Simboard application will prevent the end 
                  // user from "refreshing" the web application by asking them if they have unsaved work or not. 

      refreshGuard = true;

      alert("You can now cannot refresh the website without query blocks!");

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SRG":  // If the inputted command is "SRG" (Stop Refresh Guard), then the Simboard application will allow the end user 
                 // to "refresh" the web application swiftly with either F5 or the Refresh browser button. 

      refreshGuard = false; 

      alert("You can now refresh the website without query blocks!");

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SSV":  // If the inputted command is "SSV" (Set Specific Value), then the Simboard application will set a specific 
                 // Global Variable specified by the end user / developer. 

      newCmd = prompt("Please enter the variable, container or function (keeping Case-Sensitivity in mind) you'd like to set: ");

      newCmdDat = prompt("Please enter the data, container or function (keeping Case-Sensitivity in mind) you'd like to set: ");

      guard = confirm("This may break the functionality of Simboard, are you sure you want to proceed with this command?\n\nClick CANCEL to halt this command.\nClick OK to proceed.");

      if (guard == true) {

        resetGlobalsToDefault(`${newCmd}`, `${newCmdDat}`); // sets a specific value

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "ADG":  // If the inputted command is "ADG" (Allow Debug Guard), then the Simboard application will prevent the end 
                 // user from right clicking on the web application to access the "context menu" or "console log developer 
                 // tools". 

      debugGuard = true; 

      alert("You have disabled the ability to swiftly access the developer console tools!");

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SDG":  // If the inputted command is "SDG" (Stop Debug Guard), then the Simboard application will allow the end user 
                 // to right click on the web application to access the "context menu" or "console log developer tools".

      debugGuard = false; 

      alert("You can now swiftly access the developer console tools!");

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "MOP":  // If the inputted command is "MOP" (Move Object Position), then the Simboard application will move all Logic 
                 // Gate objects however many pixels in any direction on the Workspace. 

      movePosserX = prompt("How many pixels do you want to move all Logic Gate objects to the left by?\n\nRecommended value: 5\n\nUse POSITIVE INTEGERS to move all objects to the right\nUse NEGATIVE INTEGERS to move all objects to the left.");

      movePosserY = prompt("How many pixels do you want to move all Logic Gate objects to the left by?\n\nRecommended value: 5\n\nUse POSITIVE INTEGERS to move all objects north\nUse NEGATIVE INTEGERS to move all objects south.");

      allGates = document.querySelectorAll('div[tag^="interactableObject"]')

      allGates.forEach(connLyr => {

        target = connLyr.getBoundingClientRect();

        roundedTargetX = Math.ceil(target.left / movePosserX);

        roundedTargetY = Math.ceil(target.top / movePosserY);

        connLyr.style.left = roundedTargetX + "px";

        connLyr.style.top = roundedTargetY + "px";

      });

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SSC":  // If the inputted command is "SSC" (Screen-Shot Circuit), then the Simboard application will screenshot 
                 // the current view that the end user has of the Workspace and save it to their local storage device. 

      const circuitContainerRef = document.getElementById("Workspace");

      newCmd = prompt("If you'd like to take a screenshot of the current view of your Simboard Circuit, please enter a name for your snapshot!\n\nIf you don't want to take a screenshot anymore, simply click CANCEL.");

      if (newCmd != null) {

        html2canvas(circuitContainerRef).then(canvas => {
          
          const image = canvas.toDataURL("image/png");

          const link = document.createElement("a");

          link.href = image;

          link.download = `${newCmd}.png`; 
          
          link.click();
          
          console.log("Circuit screenshot downloaded successfully!"); // DEBUGGING INSTRUCTION ABOVE :: For telling me that 
                                                                      // all screenshot instructions processed as usual 
                                                                      // and that a download for a ".png" screenshot of the 
                                                                      // Workspace should come through soon. 

        });

      } else {

        alert("Screenshot process was cancelled!");

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SSS":  // If the inputted command is "SSS" (Screen-Shot Simboard), then the Simboard application will screenshot 
                 // what the current state of the entire Simboard application looks like and save it to their local storage 
                 // device. 

      const baseRef = document.getElementById("Base");

      newCmd = prompt("If you'd like to take a screenshot of the the entire Simboard application, please enter a name for your snapshot!\n\nIf you don't want to take a screenshot anymore, simply click CANCEL.");

      if (newCmd != null) {
        
        html2canvas(baseRef).then(canvas => {
          
          const image = canvas.toDataURL("image/png");

          const link = document.createElement("a");

          link.href = image;

          link.download = `${newCmd}.png`; 
          
          link.click();
          
          console.log("Circuit screenshot downloaded successfully!"); // DEBUGGING INSTRUCTION ABOVE :: For telling me that 
                                                                      // all screenshot instructions processed as usual 
                                                                      // and that a download for a ".png" screenshot of the 
                                                                      // entire Simboard application, including the Workspace 
                                                                      // should come through soon. 

        });

      } else {

        alert("Screenshot process was cancelled!");

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "RBC":  // If the inputted command is "RBC" (Reset Box Click (state)), then the Simboard application will reset the 
                 // "ioCheck()" related functions for debugging purposes. 

      guard = prompt("Activating this command may severely break your current circuit by confusing the connection processes.\n\nOnly click OK if ");

      hasFirstIOBeenSelected = false; 

      hasSecondIOBeenSelected = false; 

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "CSS":   // If the inputted command is "CSS" (Change Speaker Song), then the Simboard application will allow the end 
                  // user to toggle the song that plays from the speakers when simulating a circuit. 

      if (simulate != true) {

        newCmd = prompt("Please enter a number value to determine the song that you want the speaker objects to play:\n\n\n-- Music --\n0 - Bronze, by Luxury Elite\n1 - Ocean Panorama, by Late Arcane\n2 - Green Light, by Midnight Premier\n3 - My Kind Of Lady, by 318tae\n4 - The Way You Are, by Agnetha Fältskog & Ola Håkansson\n\n-- Sounds --\n5 - Chirp\n6 - Mains Hum\n7 - Nature\n8 - Long Scream\n9 - Short Scream\n10 - Radio Garble");

        if (newCmd > -1 && newCmd < 12) {

          choiceOfSongByUser = parseInt(newCmd);

        } else {

          alert("Speaker Mode not found! Please try again.");

        };

      } else { 

        alert("You must pause your circuit simulation before changing the song that your speaker objects can play!");

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "RWT":  // If the inputted command is "RWT" (Reset Workspace Transform), then the Simboard application will reset 
                 // the "transform" and "position" of the Workspace to its default state / view. 

      referenceOfWorkspace = document.getElementById("Workspace");

      viewPosX = 0; 

      viewPosY = 0; 

      currentZoomValue = 1; 

      referenceOfWorkspace.style.transform = `translate(${0}px, ${0}px) scale(${1})`;

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "VWT":  // If the inputted command is "VWT" (View Workspace Transform), then the Simboard application will output via 
                 // an "alert" the position and zoom value that the end user is currently viewing the Workspace in. 

      alert(`Your current position in the Workspace is:\n\n${viewPosX}, ${viewPosY}, ${currentZoomValue}\n\nWith ${viewPosX} value being your X position,\n${viewPosY} being your Y position\n& ${currentZoomValue} being your zoom.`)

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SWT":  // If the inputted command is "SWT" (Set Workspace Transform), then the Simboard application will allow the end 
                 // user to actually set the zoom and position of the Workspace to move to a different co-ordinate. 

      referenceOfWorkspace = document.getElementById("Workspace");

      newCmdX = prompt("Please tell Simboard the X - Co-Ordinate you want to teleport to on the Workspace: ");

      newCmdY = prompt("Please tell Simboard the Y - Co-Ordinate you want to teleport to on the Workspace: ");

      newCmdZoom = prompt("Please tell Simboard the scale you want to see the Workspace at :");

      if (newCmdZoom > zoomInLimit && newCmdZoom < zoomOutLimit) {

        viewPosX = newCmdX; 

        viewPosY = newCmdY; 

        currentZoomValue = newCmdZoom; 
        
        referenceOfWorkspace.style.transform = `translate(${newCmdX}px, ${newCmdY}px) scale(${newCmdZoom})`;

      } else {

        alert("You must enter a valid zoom value\n\n(Between 0.25 and 3)!");

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "DDV":  // If the inputted command is "DDV" (Display Debug Values), then the Simboard application will display 
                 // "debugging" values that are used consistently around the Simboard backend functions. 

      console.clear();

      console.log("JsonSave: ", jsonSaveWorkspace); // DEBUGGING INSTRUCTION ABOVE :: For notifying the end user of what 
                                                    // the jsonSaveWorkspace container holds at the current moment. 

      console.log("Previous IO Stack: ", PREVIOUSIOSTACK); // DEBUGGING INSTRUCTION ABOVE :: For notifying the end user of what 
                                                           // the PREVIOUSIOSTACK container holds at the current moment. 

      console.log("CSS TempStyleContainer == ", tempStylesContainer); // DEBUGGING INSTRUCTION ABOVE :: For notifying the end 
                                                                      // user of what the tempStylesContainer POJO (Plain Old 
                                                                      // JavaScript Object) holds at the current moment. 

      console.log("CSS Concatonates == ", cssConcatonates); // DEBUGGING INSTRUCTION ABOVE :: For notifying the end user of what 
                                                            // the cssConcatonates POJO container holds at the current moment. 

      alert("JsonSave: ", jsonSaveWorkspace);

      alert("Previous IO Stack: ", PREVIOUSIOSTACK);

      alert("CSS TempStyleContainer == ", tempStylesContainer);

      alert("CSS Concatonates == ", cssConcatonates);

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "TAN":  // If the inputted command is "TAN" (Toggle All NOTs (gates)), then the Simboard application will allow the 
                 // end user to toggle between how they want the NOT Gates to be by default (e.g. Be "ON" by default, or "OFF"). 

      NOTReferences = document.querySelectorAll('div[gatetype^="NOT"]');

      if (simulate == false) {

        newCmd = prompt("Do you want do toggle the default values of all NOT Gates when simuation starts? Enter an INTEGER VALUE to determine the default NOT mode: \n\n0 - All NOT Gates start simulation by being OFF.\n1 - All NOT Gates start simulation by being ON.");

        if (newCmd == 0) {

          notStateDefault = 0; 

          NOTReferences.forEach(cLyr => {

            cLyr.setAttribute("state", 0);

            cLyr.children[0].children[1].setAttribute("src", "/Media/DeactivatedState/NOT_Deactivated.png");

          });

        } else if (newCmd == 1) {

          notStateDefault = 1; 

          NOTReferences.forEach(cLyr => {

            cLyr.setAttribute("state", 1);

            cLyr.children[0].children[1].setAttribute("src", "/Media/ActivatedState/NOT_Activated.png");

          });

        } else {

          alert("There was an error with your input, please try again and enter either '1' or '0' to determine the default NOT state.");

        };

      } else if (simulate == true) {

        alert("Please pause the simulation of your circuit to Toggle the NOT Gates' default state.");

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "CW":  // If the inputted command is "CW" (Clear Workspace), then the Simboard application will clear the Workspace 
                // of all Logic Gates and "wire line" connections with the "clearWorkspace()" function talked about earlier. 

      guard = confirm("Are you sure you want to clear your Workspace? If you have not saved this circuit, it will be permenantly wiped forever.\n\nIf you want to proceed and clear the Workspace, click OK or press 'ENTER'.\nIf you want to cancel the procedure of clearing the Workspace, click Cancel or press 'ESC'.");

      if (guard == true) {

        clearWorkspace();

        hasFirstIOBeenSelected = false;

        hasSecondIOBeenSelected = false;

        PREVIOUSIOSTACK = ["nullpointer"];

        IOPOSITIONSTACK = [];

      } else {

        alert("Clear Workspace process was prevented.");

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "TPULSE":  // If the inputted command is "TPULSE" (Type (of) Pulse), then the Simboard application will let the end 
                    // user change the "type" of Pulse effect to be used when "binary" is "flowing through it". 

      if (simulate != true) {

        newCmd = prompt("If you'd like to change how the wires 'pulse' (look) when binary signal is flowing through them, enter an INTEGER VALUE to determine the pulse mode in the prompt below:\n\nThe default pulse mode is: River\n\n-- Pulse Types --\n0 - Static\n1 - River\n2 - Hubble\n3 - Blink\n4 - Dotted\n5 - Signal\n6 - Fountain\n7 - Flow\n8 - Invisible\n9 - Disabled\n\n");
 
        switch (parseInt(newCmd)){ // A switch statement is defined to produce an outcome depending on the parsed parameter. 

          case 0:

            abilityToPulsate = true; 

            pulseType = "static";

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

          case 1:

            abilityToPulsate = true; 

            pulseType = "river";

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

          case 2: 

            abilityToPulsate = true; 

            pulseType = "hubble";

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

          case 3:

            abilityToPulsate = true; 

            pulseType = "blink";

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

          case 4:

            abilityToPulsate = true; 

            pulseType = "dotted";

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

          case 5:

            abilityToPulsate = true;   

            pulseType = "signal";

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

          case 6:

            abilityToPulsate = true;   

            pulseType = "fountain";

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

          case 7: 

            abilityToPulsate = true;        

            pulseType = "flow";

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

          case 8:

            abilityToPulsate = true;     

            pulseType = "invisible";

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

          case 9: 

            abilityToPulsate = false; 

            break;  // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
                    // both outcomes. 

        };

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "CPULSE":  // If the inputted command is "CPULSE" (Colour (of) Pulse), then the Simboard application will let the end 
                    // user change the "colour" of the Pulse effect to be used when "binary" is "flowing through it". 

      presentPulseClr = getComputedStyle(document.documentElement).getPropertyValue('--pulseColour');

      newCmd = prompt(`Please enter a SIX DIGIT HEX VALUE to determine the colour you'd like to change all wire lines to when binary signal is flowing through them.\n\nThe default pulse colour is: #FF3300\n\nThe current Pulse Colour is: ${presentPulseClr}`);

      if (newCmd[0] == "#") {

        document.documentElement.style.setProperty('--pulseColour', `${newCmd}`);

      } else {

        alert("You must enter a valid HEX Value. Please try again!");

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "SPULSE":  // If the inputted command is "SPULSE" (Speed (of) Pulse), then the Simboard application will let the end 
                    // user change the "speed" of the Pulse effect to be used when "binary" is "flowing through it". 

      presentPulseSpd = getComputedStyle(document.documentElement).getPropertyValue('--pulseSpeed');

      newCmd = prompt(`Please enter a FLOAT / DECIMAL VALUE to determine the speed at which all wire lines pulsate at when binary signal is flowing through them.\n\nThe default pulse colour is: 5.0\n\nThe current Pulse Speed is: ${presentPulseSpd}`);

      if (newCmd >= 0) {

        document.documentElement.style.setProperty('--pulseSpeed', `${newCmd}`+'s');

      } else {

        alert("You must enter a valid FLOAT / DECIMAL Value. Please try again!");

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "WPULSE":  // If the inputted command is "WPULSE" (Width (of) Pulse), then the Simboard application will let the end 
                    // user change the "width / thickness" of the Pulse effect to be used when "binary" is "flowing through it". 

      presentPulseWid = getComputedStyle(document.documentElement).getPropertyValue('--pulseWidth');

      newCmd = prompt(`Please enter a FLOAT / DECIMAL VALUE to determine the width that all wire lines will appear as when binary signal is flowing through them.\n\nThe default pulse width is: 7.5\n\nThe current pulse width is: ${presentPulseWid}`);

      if (newCmd >= 0) {

        document.documentElement.style.setProperty('--pulseWidth', `${newCmd}`);

      } else {

        alert("You must enter a valid FLOAT / DECIMAL Value. Please try again!");

      };

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    case "TT":  // If the inputted command is "TT" (Toggle Transparency), then the Simboard application will allow the end user 
                // to toggle the transparency of the "Toggle Assist" when hovering over the "Hold Button"s. 

      presentToggleTransparency = getComputedStyle(document.documentElement).getPropertyValue('--toggleTransparency');

      newCmd = prompt(`Please enter an opacity NUMBER VALUE between 1.0 (Fully Transparent) and 0.0 (Fully Solid) to determine the transparency of the Button Object hover assist toggle. \n\nCurrent toggle assist opacity value is: ${presentToggleTransparency}`);
      
      document.documentElement.style.setProperty('--toggleTransparency', `${newCmd}`);

      break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
             // both outcomes. 

    default:  // If the end user has not inputted a command, then control flow will go into the instructions below: 
                // !-> "default" acts as the "else" statement, but for "switch" case instructions. 

      console.warn(" No command (Abbreviated CMD) was entered into the prompt.\n\nIf you are unsure of what to enter, type the command 'MENU' into the 'Talk To System' prompt to see the catalouge of commands to use, thank you! ");
      // DEBUGGING INSTRUCTION :: I should be alerted to control flow reaching this "default" state if no other "case" outcomes 
      // are met. 

      alert(" No command (Abbreviated CMD) was entered into the prompt.\n\nIf you are unsure of what to enter, type the command 'MENU' into the 'Talk To System' prompt to see the catalouge of commands to use, thank you! ");
      // The end user should also be alerted to the fact that they entered an erroneous command, to which solutions are 
      // provided in-prompt for the correct commands and syntax to use. 

    break; // This prevents propogation into the next case, essentially acting as a "barrier" or "border" between 
           // both outcomes. 
      
  };  // The switch statement for the command cases for Simboard control ends here. 

};  // The "talkToSystem()" function which acts as a controller for Simboard operations ends here. 



// *** SCRIPT 045 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 046 *** -- Starts here 
// The purpose of the below code is to reset all or some variables to their default contents, or to even 
// set specific variables to a value by force. This allows the end user to manually debug if something 
// cannot or is not automatically fixed by the various systems, measures and functions put in place, or to 
// stress-test the Simboard application to their will. 



function resetGlobalsToDefault(specificAddress, forceValue) { // This function is used and called for modifying values 
                                                              // for Simboard. This could be for debugging, and needs 
                                                              // two parameters, one for the Variable to modify, and the 
                                                              // other for the value to set said Variable to. 

  if (specificAddress == null && forceValue == null) {  // If both the Variable and Value inputted are "null", then 
                                                        // all of the Global Variables that make up Simboard are reset 
                                                        // to their default state. 

    simboardVersion = "FR 1.0.0"; // This variable is for the saving process for future compatibility. 

    simulate = false;     // This variable holds the state that decides if Simboard should enter "Simulation" mode or not. 
                          // It is toggled to FALSE by default to allow the end user to create a circuit.

    refreshGuard = true;  // This variable holds the state that decides if Simboard should be able to refresh without 
                          // being interrupted by a "Are you sure you want to clear unsaved work" type of prompt. 
                          // If true, then this pop-up will occur, and the opposite if false.  

    debugGuard = true;    // This variable holds the state that decides if the end user can access the Console Developer 
                          // tools inbuilt in the browser by default. 


    viewPosX = 0;         // This variable holds the value of the X-Position that the Workspace is positioned at. It starts 
                          // at 0 so the Workspace is loaded in its default state.

    viewPosY = 0;         // This variable holds the value of the Y-Position that the Workspace is positioned at. It starts 
                          // at 0 so the Workspace is loaded in its default state.

    currentZoomValue = 1; // This variable holds the float value of the Workspace scale. At value 1, the Workspace is at 
                          // 100% zoom (default). When this changes, for example, to 0.5, the Workspace is scaled to 50% 
                          // of its original zoom. Or, for example, to 2.5, the Workspace is scaled to 250% of its 
                          // original zoom. 

    zoomOutLimit = 3;     // This variable holds the limit that the Workspace can scale to. If the Workspace is at 300% 
                          // of its original scale, then it cannot scale larger any further. 

    zoomInLimit = 0.25;   // This variable holds the limit that the Workspace can scale to. If the Workspace is at 25% 
                          // of its original scale, then it cannot scale down any further. 

    traverseSpeed = 35;   // This variable holds the movement speed that the end user can travel and transform the Workspace 
                          // by. If the end user taps either one of the arrow keys, the Workspace will move 35 pixels (px) in 
                          // that same direction.

    cssConcatonates = [ // This object holds the references of the HTML UI Sections that can be customised with the "Customise"
                        // function in Simboard. (e.g. changing the Colouring, the Opacity, etc.)

      GridCanvasColour = document.getElementById('GridCanvas'),   // This essentially refers to the Workspace Background

      ObjectMenuColour = document.getElementById('ObjectMenu'),   // This essentially refers to the Object Menu Background 

      FileMenuColour = document.getElementById('FileMenu'),       // This essentially refers to the bit behind the File Menu buttons 

      CircuitConfigColour = document.getElementById('CircuitConfigurationArea'),  // This essentially refers to the whole File Menu 

      ObjectMenuButtonColour = document.getElementById('ObjectMenu').children,    // This refers to all HTML child elements inside of the 
                                                                                  // object menu.

      FileMenuButtonColour = document.getElementById('FileMenu').children,        // This refers to all HTML child elements inside of the 
                                                                                  // file menu.

      GridLineColour = "#000000", // This refers to the grid lines / grid squares in the background of the Workspace. 

      AxisXColour = "#CD5C5C",    // This refers to the X Axis (Horizontal Line) in the background of the Workspace. 

      AxisYColour = "#4EB842",    // This refers to the Y Axis (Vertical Line) in the background of the Workspace. 

    ]; // This signifies the end of the object, and everything inside can be referred to as an index of cssConcatonates. 

    HEXValidator = null; // This variable stores the string OR value that was entered into the prompt when the end user utilises the 
                        // "Customise" function in Simboard. 

    tempStylesContainer = {};  // This is a POJO! (Plain Old JavaScript Object) and contains the temporary values that 
                              // should be associated with their respective UI elements seen in cssConcatonates. 

    tempStylesContainer.tempCanvasColour = "#DEDE94";         // This essentially refers to the Workspace Background.

    tempStylesContainer.tempObjectMenuColour = "#A4A4A4";     //This essentially refers to the Object Menu Background 

    tempStylesContainer.tempFileMenuColour = "#808080";       //This essentially refers to the bit behind the File Menu buttons 

    tempStylesContainer.tempCircuitConfigColour = "#808080";  //This essentially refers to the whole File Menu 

    tempStylesContainer.tempObjectMenuButtonColour = "#DEDE94"; //This refers to all HTML child elements inside of the 
                                                                  // object menu.

    tempStylesContainer.tempFileMenuButtonColour = "#DEDE94";   //This refers to all HTML child elements inside of the 
                                                                  // file menu.

    tempStylesContainer.tempGridLineColour = "#000000"; //This refers to the grid lines / grid squares in the background of the Workspace. 

    tempStylesContainer.tempAxisXColour = "#CD5C5C";    //This refers to the X Axis (Horizontal Line) in the background of the Workspace.

    tempStylesContainer.tempAxisYColour = "#4EB842";    //This refers to the Y Axis (Vertical Line) in the background of the Workspace. 

    tempStylesContainerOverwrite = {};  // This POJO is utilised when UI Layout data is being re-imported from a save file, 
                                        // and can be seen as the "Temporary Reserve" for said data when everything is being 
                                        // redrawn. 

    xLen = document.getElementById("GridCanvas").width;   // Defines how long a Workspace background object should stretch on the X Axis (e.g. Grid, Axis, Background)

    yLen = document.getElementById("GridCanvas").height;   // Defines how long a Workspace background object should stretch on the Y Axis (e.g. Grid, Axis, Background)

    hasFirstIOBeenSelected = false; // This is a global variable that determines whether the first Input or Output has been Selected 

    hasSecondIOBeenSelected = false; // This is a global variable that determines whether the second Input or Output has been Selected

    PREVIOUSIOSTACK = ["nullpointer"]; // Holds the custom ID's of each Input or Output box on a gate that has been selected (clicked) on. 

    IOPOSITIONSTACK = []; //Holds the actual HTML references of each Input or Output box on all gates that have been selected. 

    DRAWBOXSTACK = [];  // This holds the HTML references of the pair of gates that are to be connected together via a wire. 

    var IOPARSE = []; // This is an object that holds integral information about the Input or Output box so that it can be parsed 
                      // to any function that calls it. 

    IOPARSE.INPUTPOSITIONX = 0; // This attribute of the IO (Input/Output) object holds the X Axis position that the Input Box of the 
                                // connected pair of gates will be positoned on. 

    IOPARSE.INPUTPOSITIONY = 0; // This attribute of the IO (Input/Output) object holds the Y Axis position that the Input Box of the 
                                // connected pair of gates will be positoned on. 

    IOPARSE.OUTPUTPOSITIONX = 0; // This attribute of the IO (Input/Output) object holds the X Axis position that the Output Box of the 
                                // connected pair of gates will be positoned on. 

    IOPARSE.OUTPUTPOSITIONY = 0; // This attribute of the IO (Input/Output) object holds the Y Axis position that the Output Box of the 
                                // connected pair of gates will be positoned on. 

    IOPARSE.INPUT = null; // This attribute holds the Input Box's actual HTML reference so that this system can know what objects are 
                          // paired together. 

    IOPARSE.OUTPUT = null;  // This attribute holds the Output Box's actual HTML reference so that this system can know what objects are 
                            // paired together.   

    gatePositionXGlobalReference = 0; // This is a global variable that holds the X Axis position that the selected gate lies on in the 
                                      // workspace. 
    gatePositionYGlobalReference = 0; // This is a global variable that holds the Y Axis position that the selected gate lies on in the 
                                      // workspace. 

    searchIndex = 0; // This variable holds the true number of total connections between object pairs in the Workspace. 
                    // searchIndex is often used for wire line (connection path) traversal. 

    selectedGatesStack = [];  // Every time an object in the Workspace is selected, its HTML reference is pushed to this stack so that 
                              // interactivity can be validated and worked upon. 

    totalSelectedGates = 0; // This holds the number total of the amount of selections on gates that have been registered. 

    presentObjects = +0; // This holds the number of objects that are present in the Workspace (ones that have been spawned in, but 
                        // not deleted).

    jsonSaveWorkspace = [];  // This holds all data for the logic gates present on the workspace plus connections. 

    jsonSaveWorkspaceOverwrite = []; // This object/array acts as the "Temporary Reserve" when importing Circuit Layout Data
                                    // and contains all connected pairs of objects that are inside of the Save File. 

    connectionsInitialised = 0 + searchIndex; // This variable stores the number of total wires initialised on the Workspace. This 
                                              // will be appended to the unique ID's of each Wire 

    importedFileType = null; // This variable stores the type of save file imported into Simboard. This is done by reading the header 
                            // in the save file, and collecting the mode, and then pasting it into this variable. 
                            // By doing this, redrawing and reimporting functions can understand if the save file stores UI Layout 
                            // data or circuit project data. 

    speakerIdentifications = [ // This object array stores music songs that can play out of speakers when the circuit is simulating!

      "/Media/Audio/speakerSong0.mp3", // This is the default, upbeat song: Bronze - (by) Luxury Elite

      "/Media/Audio/speakerSong1.mp3", // This is another upbeat song: Ocean Panorama - (by) Late Arcane 

      "/Media/Audio/speakerSong2.mp3", // This is another upbeat song: Green Light - (by) Midnight Premier 

      "/Media/Audio/speakerSong3.mp3", // This is another upbeat song: My Kind Of Lady - (by) 318tae

      "/Media/Audio/speakerSong4.mp3", // This is another upbeat song: The Way You Are - (by) Agnetha Fältskog & Ola Håkansson

      "/Media/Audio/chirp.mp3", //  This is the sound of a fire alarm "chirp".

      "/Media/Audio/mainsHum.mp3", // This is the sound of a microwave humming. 

      "/Media/Audio/nature.mp3", // This is a sound of birds tweeting in the green, rural woods. 

      "/Media/Audio/scream0.mp3", //  This is the sound of someone screaming for a long amount time. 

      "/Media/Audio/scream1.mp3", //  This is the sound of someone screaming for a short amount time. 

      "/Media/Audio/radio.mp3" // This is the sound of an annoying troglodyte talking for minutes on end. 

    ]; // The audio container ends here. 

    choiceOfSongByUser = 0; // This is a variable that holds the index of the speaker song to play, in the 
                            // "speakerIdentifications" object/array.

    abilityToPulsate = true; // This is a variable that holds a Boolean TRUE || FALSE value which states 
                            // whether the user wants to see their wires display an effect when binary 
                            // signal "flows" through them. 

    pulseType = "river"; // This is a variable that holds a string value that determines what the wire 
                        // "pulsation" effect should look like. This is used to refer to the CSS Classes
                        // defined earlier in the Stylesheet, that initialise the HTML Path/Line animations. 

    notStateDefault = 1; // This variable holds the mode that all NOT gates follow. If this variable holds the 
                        // value "1", then all NOT gates start off with a state of "1", yet if this variable 
                        // holds the value "0", then all NOT gates start off with a state of "0". By default, 
                        // all NOT gates should have a state of "1" to invert the incoming signals. 

  } else if (forceValue == null) {  // If just the Value inputted is "null", then the Variable specified will be reset 
                                    // to "null". 

    specificAddress = null; 

  } else {  // If just the Value and Variable inputted are not "null", then thef Variable specified will be set to whatever 
            // the end user has stated. 

    specificAddress = forceValue; 

  };  // The conditional branch for what occurs when the end user has inputted specific parameters ends here. 

};  // The function for resetting OR setting Global Variables in Simboard ends here. 



// *** SCRIPT 046 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 047 *** -- Starts here
// The purpose of this code is to configure all wire line connections to appear to "pulsate" via a cool 
// effect defined in the stylesheet. There are various effects, and this function styles a specific HTML 
// path to inherit the "pulsation" style classes seen in the CSS Stylesheet (e.g. ".flow" or ".hubble" 
// etc.), or removes said "pulsation" style class if the wire is said to be off. This function is 
// especially used in SCRIPT 041, aka. the discernBoolean() function, and SCRIPT 038, aka. the Simulation 
// toggle function, where both functions iterate through lines and repeatedly call this function for 
// said line to either activate its visual "pulse" effect when Binary / Boolean signal flows through it, 
// or to revert its visual state to its default setting either configured by the system, or by the end 
// user.  



function wireLinePulsate(pathRef, pathState) {  // When this function is called, which changes "wire lines" to 
                                                // look like their "Pulsating", it needs two parameters. Firstly, 
                                                // the HTML DOM reference of the "Wire Line" is necessary as a
                                                // HTML Path is needed to be styled. Also, the state that determines 
                                                // whether the HTML Path will "Pulsate" or not has to be parsed in 
                                                // too, to determine how this function will approach styling the 
                                                // "wire line". 

  if (abilityToPulsate == true) { // If the end user has enabled the ability for "wire lines" to pulsate in the 
                                  // "Talk To System" function (the default choice), then control flow will branch 
                                  // into the instructions below. 

    console.log(pathRef, pathState); // DEBUGGING INSTRUCTION ABOVE :: For telling me about the specific wire 
                                     // that is to be "pulsating". This is important for validation and 
                                     // debugging. 

    if (pathRef) {  // A small Guard to prevent errors is put in place, which actually validates that the HTML Path 
                    // "Wire Line" exists before it is styled, otherwise unexpected or critical errors could arise. 

      if (pathState == true) {  // If this function was called with the need to allow the parsed "wire line" to 
                                // "pulsate", then control flow goes into this branch here. 

        pathRef.classList.add(`${pulseType}`);  // The styling class which plays a "pulsation" animation, which can 
                                                // be determined by the end user (in the Talk To System function) 
                                                // is added to the HTML Path / "wire line", in order to display a 
                                                // visual "binary flowing" effect for beginner users to see how 
                                                // logic operates in the bigger picture for Logic Gate circuits. 

      } else {  // If this function was called with the need to allow the parsed "wire line" to stop "pulsating", 
                // then control flow goes into this branch here. 

        pathRef.classList.remove(`${pulseType}`); // The styling class which plays a "pulsation" animation, which can 
                                                  // be determined by the end user (in the Talk To System function) 
                                                  // is removed from the HTML Path / "wire line", and said "wire line" 
                                                  // returns to how it looked before the "pulsation" effect was applied 
                                                  // to it. 

      };  // The branching for if this function was called to add a "pulsation" effect to a "wire line" or not ends 
          // here. 

    };  // The validator / checker which sees if the HTML Path being parsed exists or not in the HTML DOM ends here.  

  };  // The validator / checker which sees if the end user has enabled or disabled the ability to pulsate the "wire 
      // lines" (in the Talk To System function) ends here. If the end user did disable this feature, then control 
      // flow will not go into this branch, and nothing will happen to the parsed "wire line" when it is sent into 
      // this function. 

};  // The function which allows "wire lines" to "pulsate" / "play an animation" when binary signal is flowing through it 
    // ends here. 



// *** SCRIPT 047 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 048 *** -- Starts here
// The purpose of this code is to prevent the end user from natively refreshing the Simboard web 
// application. This prevents mistakes and accidents when the end user is working on a Logic Gate project, 
// and accidentally refreshes the page which causes the permenant loss of all of their hard work. This 
// guard (safety measure) however, can be disabled in the "Talk To System" function by entering the 
// ACMD (Abbreviated Command) / CMD (Command (for short...)) "SRG" which stops the Refresh Guard from 
// prompting the end user on if they want to leave or refresh the web application page. If the end user 
// wants to activate it again, they can enter the ACMD / CMD "ARG", which re-allows the Refresh guard 
// to enact its safety measures to full extent. 



window.addEventListener('beforeunload', function (e) {  // An event listener is attached not to the hardware 
                                                        // that the end user is using to operate the Simboard 
                                                        // application, but to the Browser (software) instead. 
                                                        // Information about the browser, and its state is also 
                                                        // parsed as a parameter into this event listener, which 
                                                        // waits until the Browser "refreshes", which in that 
                                                        // scenario, will allow control flow to instantly 
                                                        // branch into the instructions below. 

  if (refreshGuard == true) { // If the end user has enabled their "Refresh Guard" (the default setting), then 
                              // control flow will branch into here when the end user refreshes or visits 
                              // another web page. 

    e.preventDefault();   // The default "outcome" of refreshing the web page is disabled and ignored, which 
                          // means that the Browser has to wait until the end user makes a decision on the 
                          // dialouge box seen in the instruction below. 
    
    e.returnValue = 'Changes you made may not be saved. Are you sure you want to leave?'; // This message pops 
                                                                                          // up when the end user 
                                                                                          // tries to refresh the 
                                                                                          // web page, which gives 
                                                                                          // said end user the ability 
                                                                                          // to Leave / Refresh Simboard, 
                                                                                          // or to cancel their operation. 
                                                                                            // !-> This prevents the end 
                                                                                            //     user from accidentally 
                                                                                            //     losing their work or 
                                                                                            //     Simboard project! 

  };  // The validator to check if the Refresh Guard is enabled when the end user leaves / refreshes the Simboard web 
      // application ends here. If the Refresh Guard is disabled, no dialouge box will pop up, and the Browser operation 
      // will continue like normal. 

}); // The event listener that checks if the browser is refreshing or not ends its operation here. 


// *** SCRIPT 048 *** -- Ends here 
//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-

//~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-~¬-
// *** SCRIPT 049 *** -- Starts here
// The purpose of this code is to enact a similar protocol to SCRIPT 048, aka. the function that permits 
// the debug guard, however, is different. This is because instead of guarding the refresh ability, this 
// guard prevents the end user from accessing the Browser Developer Tools / Console Log. This is to 
// ensure that the end user doesn't accidentally mess up the structure or styling of the application 
// by squeezing Simboard into a smaller fraction of the screen. Also, this prevents accidental 
// functionality breaking outcomes to occur, if the end user were to accidentally input a certain 
// command into the Dev / Console Log. Yet, this can be disabled in the "Talk To System" function by 
// entering the ACMD / CMD "SDG" which stops the Debug guard from doing its thing. And just like the 
// previous script, SCRIPT 048, the Debug guard can be re-enabled by entering the ACMD / CMD "ADG" into 
// the "Talk To System" function. 



document.addEventListener('contextmenu', function(e) {  // An event listener which checks if the end user 
                                                        // has right clicked on the Simboard web application 
                                                        // to open the "context" menu starts here. 
                                                        // Relevant information about said action is taken 
                                                        // as a parameter too. 

  if (debugGuard == true) { // If the end user has enabled their "Debug Guard" (the default setting), then 
                            // control flow will branch into here when the end user right clicks anywhere on 
                            // the Simboard web page. 

    e.preventDefault(); // The default outcome of right clicking anywhere on Simboard is prevented, and 
                        // stops the "context" menu appearing which can act as a pathway to the "console 
                        // log developer tools". 

  };  // The validation check which determines if the Debug Guard allows control flow to prevent the end user 
      // from accessing the "context menu" / "console log developer tools" or not ends here. 

}, false);  // The event listener that checks if the end user is trying to access the "context menu" ends its 
            // operation here, and returns "False" to the browser to prevent said "context menu" from appearing 
            // upon right click. 



